export const YUFAN_ITEMS = [{"topicId":"g-adj-adv","newTopic":false,"title":"形容词","sourceDirs":["yufan/形容词"],"imagesRead":15,"summary":"形容词修饰名词，说明人或事物的性质与特征；分性质形容词、叙述形容词和其他形容词，可作定语、表语和宾语补足语，并具有比较等级的变化。","intro":"按教材第 5 章顺序整理：种类与位置 → 比较等级的构成 → 原级、比较级、最高级的句型 → 章末常见失分陷阱。","notes":"第 15 张（微信图片_20260927093025_325_66.jpg）为章末「实力测验」，12 题选词填空 + 6 题汉译英，原书未附答案，未录入正文。","extras":{"forms":[{"name":"倍数与半数（原级）","pattern":"...times / half + as + 形容词原级 + as","note":"倍数表示「是……的几倍」，half 表示「是……的一半」。"},{"name":"越……越……","pattern":"the + 比较级 + ..., the + 比较级 + ...","note":"表示后者随前者变化。"},{"name":"两者中较……的","pattern":"the + 比较级 + of the two","note":"此时比较级前要加 the。"},{"name":"比其他任何……都……","pattern":"比较级 + than any other + 单数名词","note":"用比较级形式表达最高级含义；any other 后接单数名词。"}],"points":[{"title":"形容词修饰复合不定代词时要后置","desc":"something、anything、nothing 等复合不定代词被形容词修饰时，形容词放在后面。","good":["There is something wrong with this watch.","Is there anything important in the newspaper?"],"bad":["There is wrong something with this watch."]},{"title":"the + 形容词表示一类人或事物","desc":"the young / old / rich / poor 等作主语时看作复数；the beautiful / impossible 等表示一类事物时看作单数。","good":["Robin hated the rich and loved the poor.","The wounded / old are well looked after."],"bad":[]},{"title":"量度在前，形容词要后置","desc":"名词前有量度词组，或量度词组作表语时，形容词放在后面。","good":["London is a city about two thousand years old.","The bridge is a hundred metres long."],"bad":["London is a city about two-thousand-year old."]}],"contrasts":[{"title":"三种形式表达同一个最高级含义","head":["形式","结构","例句"],"rows":[["最高级","the + 最高级 + in / of","She is the best in her class."],["比较级","比较级 + than any other + 单数名词","She is better than any other student in her class."],["比较级（否定式）","no other + 名词 + be + 比较级 + than","No other student in her class is better than she."],["原级（否定式）","no other + 名词 + be + as + 原级 + as","No other student in her class is as good as she."]]},{"title":"形容词位置速查","head":["位置","条件","例句"],"rows":[["名词前","一般定语（冠词 / 代词 + 形容词 + 名词）","a beautiful girl"],["名词后","修饰复合不定代词","something wrong"],["名词后","名词前有量度的词或词组","a building thirteen storeys high"],["句首或句尾","形容词（词组）作状语","Cold and hungry, he walked in the street."]]}],"pitfalls":["修饰 something / anything / nothing 等复合不定代词的形容词必须后置：something new，不是 new something。","疑问句和否定句中用 anything，肯定句中用 something。","ill 只作表语，作定语要用 sick（the sick man）。","half、times 等倍数、半数结构后面接原级：three times as long as。","最高级前的 the 不能丢，one of the + 最高级 后面的名词必须用复数。"],"examTips":["形容词比较等级是各地中考单项填空的固定考点：看到 than 或「两者」选比较级，看到 one of / in + 范围选最高级。","复合不定代词 + 形容词后置、倍数 / 半数结构、any other + 单数名词是近年中考的高频陷阱（福州、上海等）。","题干出现 but、than 之类的信号词时，先确定比较对象和比较方向，再决定形式。"],"memoryCard":["两两比较用 than，三者以上加 the。","something / anything 后面才放形容词。","倍数、半数都接原级：three times as long as。","the + 形容词 = 一类人（看作复数）。"]},"sectionCount":8},{"topicId":"g-adj-adv","newTopic":false,"title":"副词","sourceDirs":["yufan/副词"],"imagesRead":21,"summary":"副词修饰动词、形容词、副词或整个句子，按意义分方式、程度、地点、时间、频度、疑问等类别，位置和比较等级都有固定规则。","intro":"按教材第 6 章顺序整理：种类与句法功能 → 位置 → 比较等级 → 常见副词辨析 → 形容词与副词的区别 → 章末常见失分陷阱。","notes":"第 19—21 张（微信图片_20260927093558_344_66.jpg、…345_66.jpg、…346_66.jpg）为章末「实力测验」，共 4 组练习（词形变换、用括号中适当的词填空、改写句子、选择填空），原书未附答案，未录入正文。","extras":{"forms":[{"name":"副词原级","pattern":"as + 副词原级 + as","note":"表示「A 和 B 一样……」；否定用 not so / as ... as。"},{"name":"副词比较级","pattern":"副词的比较级 + than","note":"表示「A 比 B 更……」。"},{"name":"副词最高级","pattern":"(the) + 副词最高级 + in / of...","note":"副词最高级前的 the 可以省略。"},{"name":"越……越……","pattern":"the + 比较级 ..., the + 比较级 ...","note":"如 The busier he is, the happier he feels."},{"name":"尽可能……","pattern":"as + 副词原级 + as one can / as possible","note":"两种搭配都表示「尽可能……」。"}],"points":[{"title":"句末多个副词的顺序","desc":"句末同时出现几个副词时，基本顺序是：方式副词 + 地点副词 + 时间副词。","good":["They did their experiments carefully in the lab yesterday.","The students all worked well here last week."],"bad":[]},{"title":"频度副词与程度副词的位置","desc":"频度副词与修饰动词的程度副词，位于 be 动词、情态动词和第一个助动词之后；位于行为动词之前。","good":["She is always kind to us.","He has never been abroad.","I quite like the boy."],"bad":["She always is kind to us.","He never has been abroad."]},{"title":"系动词后用形容词，行为动词后用副词","desc":"be、taste、sound、smell、feel、look、seem、appear、get、become、turn、grow 等系动词后接形容词；行为动词用副词修饰。","good":["The dish tastes delicious.","She dances well.","I did well on the exam and got a good grade."],"bad":["The dish tastes deliciously.","She dances good.","I did good on the exam."]}],"contrasts":[{"title":"形容词 vs 副词","head":["比较项","形容词","副词"],"rows":[["作用","修饰名词和代词，回答 which one / what kind / how many","修饰动词、形容词、副词或整个句子，回答 when / where / how / how often / how much"],["构词","名词 + -y / -ful / -less","形容词 + -ly；y 结尾先变 i 再加 -ly"],["位置","名词前；修饰复合不定代词时后置","句末（地点、时间、方式）；be / 情态 / 助动词后或行为动词前（频度、程度）"],["谓语动词","系动词后作表语","行为动词后作状语"]]},{"title":"too / either / also / neither","head":["词","用于","位置"],"rows":[["too","肯定句","句末，前面常用逗号隔开"],["either","否定句","句末"],["also","肯定句（较正式）","句中，与频度副词位置相同"],["neither","表示「两者都不」","可置于句首引起倒装"]]},{"title":"ago vs before","head":["词","基准","常连用的时态 / 场景"],"rows":[["ago","以现在为基准，指「距今若干时间以前」，不能单独使用","一般过去时（three days ago）"],["before（+ 若干时间）","以过去为基准，指「距过去若干时间以前」","间接引语中的过去完成时"],["before（单独使用）","泛指「以前」，时间不确切","现在完成时"]]}],"pitfalls":["seldom、never、hardly 本身表示否定，句子不再用 not，反意疑问句要用肯定形式：He seldom watches TV in the daytime, does he?","hardly 意为「几乎不」，与 hard（努力地）完全不同：His parents hardly hit him.","very 修饰原级，much 修饰比较级；不能按汉语语序说 I very much like English.","enough 修饰形容词、副词时要后置：big enough、fast enough。","回答 How（怎么样）要用副词，回答 What kind（什么样的）要用形容词。","-ly 结尾不一定都是副词：friendly、lonely、lovely、oily 是形容词。"],"examTips":["副词的比较等级与形容词同步考查：看到 than 用比较级，看到 in / of + 范围用最高级。","how long / how soon / how often / how far 的辨析、too / either / also 的辨析是中考常见陷阱。","形容词还是副词的判断先看谓语动词：系动词后用形容词，行为动词后用副词。"],"memoryCard":["修饰动词、形容词、副词、句子——副词四用。","方式 + 地点 + 时间：句末副词的基本顺序。","频度、程度副词：be 后、情态后、助动词后；行为动词前。","enough 永远后置。","hard 努力 / hardly 几乎不；high 高 / highly 高度地。"]},"sectionCount":7},{"topicId":"g-agreement","newTopic":true,"title":"主谓一致","sourceDirs":["yufan/主谓一致"],"imagesRead":15,"category":"句法","difficulty":4,"summary":"主语的单复数决定谓语动词的形式。先掌握语法一致、意义一致、就近一致三条原则，再按主语类型（并列主语、不定代词、集体名词、数量短语、从句等）逐类处理特殊情况。","intro":"主谓一致难在“形式”与“意义”不一致：主语形式是单数、意义是复数时用复数谓语（如 The crowd were fighting for their lives.），反之用单数谓语（如 Twenty dollars is too dear.）。做题时先定位真正的主语，忽略插入语和修饰语。","forms":[{"name":"语法一致原则","pattern":"语法形式是单数的主语 + 单数谓语；语法形式是复数的主语 + 复数谓语","note":"His father is a doctor. / The twins have found their mother."},{"name":"意义一致原则","pattern":"按主语表达的内在含义决定谓语单复数","note":"Twenty dollars is too dear. / The crowd were fighting for their lives."},{"name":"就近一致原则","pattern":"谓语与邻近的主语保持人称和数的一致","note":"Neither you nor your brother has passed the exam."},{"name":"并列连词连接主语","pattern":"A or B / either A or B / neither A nor B / not only A but (also) B + 谓语","note":"谓语与后一个主语一致：Either he or I am wrong."},{"name":"主语 + 插入语","pattern":"主语 + as well as / with / together with / rather than / but / except … + 谓语","note":"谓语仍与主语一致：Nobody but us knows it."}],"points":[{"title":"就近一致：or / either…or / neither…nor / not only…but also","desc":"谓语动词与最靠近它的那个主语保持人称和数的一致。","good":["Tom or his brothers are waiting in the room.","Neither the students nor the teacher knows anything about it.","Not only the students but also the teacher is active in sports and games."],"bad":["Neither the students nor the teacher know anything about it."]},{"title":"插入语不影响主语的数","desc":"主语后接 as well as、with、together with、rather than、but、except 等短语时，谓语动词仍与主语一致。","good":["The teacher, together with his students, is visiting the museum.","Nobody but us knows it.","I, rather than you, am to blame."],"bad":["The teacher, together with his students, are visiting the museum."]},{"title":"each / every / no 修饰的单数主语，即使并列也用单数谓语","desc":"不定代词 each、every、no 所修饰的单数可数名词，即使以 and 或逗号连接成多个并列主语，谓语仍用单数。","good":["Each boy and each girl wants to serve the people in the future.","Every man and woman attends the meeting."],"bad":["Each boy and each girl want to serve the people in the future.（each 所修饰的并列主语，谓语仍用单数）"]},{"title":"and 连接的主语看“同一概念”还是“不同概念”","desc":"表示不同概念用复数谓语；表示同一概念用单数谓语，且只在第一个名词前加修饰语。","good":["The singer and the dancer come from Guangxi.（两个人）","The singer and dancer comes from Guangxi.（同一个人）","The tenth and last chapter is difficult to understand.（同一章）"],"bad":["The singer and dancer come from Guangxi.（同一个人时应用单数）"]},{"title":"one of + 复数名词 + 定语从句的谓语","desc":"定语从句谓语与靠近的复数名词一致（用复数）；但 one 前有 the (only) 时，从句谓语用单数。","good":["This is one of the most interesting questions that have been asked.","She was the only one of the girls who was late for the meeting."],"bad":["This is one of the most interesting questions that has been asked.（定语从句的谓语应与靠近的复数名词一致，用 have）"]},{"title":"the number of 用单数，a number of 用复数","desc":"“the number of + 复数名词”作主语，谓语用单数；“a number of + 复数名词”作主语，谓语用复数。","good":["The number of students in our school is 1,123.","A number of students like playing football."],"bad":["The number of students in our school are 1,123."]}],"pitfalls":["谓语只与真正的主语一致，不要被 with / together with / as well as / but / except 等插入语带偏。","主语是单数、意义是复数（The crowd were…）或形式是复数、意义是单数（Twenty dollars is…）时，一律按意义一致处理。","people、police、cattle 作主语时，谓语只能用复数形式。","“the + 形容词/过去分词”表示一类人时谓语用复数（The injured have been taken to hospital.），但表示某个人或物时用单数（The wounded is a friend of his.）。","glasses、trousers、clothes、shoes 等以 -s 结尾的名词作主语用复数谓语，但前面有 a pair of / a kind of 等时，谓语随 pair、kind 的数变化。","each 位于复数主语之后不影响主语的数：The boys each have an apple."],"examTips":["先划出真正的主语（划掉插入语和定语从句），再判断单复数，是这类题最快的方法。","看到 or / either…or / neither…nor / not only…but also 立刻用就近一致；看到 the number of / a number of 立刻区分单复数。","分数、百分数、part of、a lot of、the population 等作主语时，一律看 of 后面的名词（或所表示的概念）：复数概念用复数，单数/不可数概念用单数。"],"memoryCard":["三原则：语法一致、意义一致、就近一致。","插入语不改变主语：with、as well as、but、except 都忽略。","the number of 单，a number of 复；people / police / cattle 只复。"],"notes":["图片 微信图片_20260927174524_614_66.jpg 为第 22 章章首页（名人名言页），无语法正文，已记录其名言与译文。","实力测验部分跨页（第 416、418、419 页），个别题目的选项在页边被裁切，已按可辨识内容转写；这些原题图片中未给出答案。","以下图片内容清晰、可逐字转写：615—628。无完全不可识别的图片。"],"sectionCount":8},{"topicId":"g-articles","newTopic":false,"title":"冠词","sourceDirs":["yufan/冠词"],"imagesRead":13,"summary":"冠词是虚词，本身无词义也不能单独使用，用在名词前帮助指明名词的含义；分为不定冠词 a/an 和定冠词 the。","intro":"不定冠词仅用在单数可数名词前面，表示“一”的意义，但不强调数目观念；定冠词表示特定的一个或一类人、事物，在可数名词的单、复数及不可数名词前都可以使用。","extras":{"forms":[{"name":"不定冠词选择 a 还是 an","pattern":"看紧跟其后的那个词的读音：辅音音素前用 a，元音音素前用 an","note":"a university；an hour；an honest boy；a European country"},{"name":"定冠词 the 的读音","pattern":"辅音音素前弱读 [ðə]；元音音素前重读 [ði]","note":"the situation [ðə]；the old people [ði]"},{"name":"the + 比较级…, the + 比较级…","pattern":"表示“越……越……”","note":"The more you eat, the fatter you get."},{"name":"the + 形容词","pattern":"表示某一类人，谓语动词用复数","note":"the rich / the poor / the blind / the young"}],"points":[{"title":"定冠词用于“重新提到”的事物","desc":"第一次提到用不定冠词，第二次提到（特指前面那个）用定冠词。","good":["He wrote a book last year. The book is about gardening.","I have a beautiful wallet, but the wallet was stolen yesterday."],"bad":["I have a beautiful wallet, but a wallet was stolen yesterday.（特指前面那个钱包应用 the）"]},{"title":"有无冠词含义不同","desc":"go to school / church / market / bed 指与处所功能有关的活动时不加冠词；指具体地点或因其他目的前往时要加 the。","good":["go to school (to study) 去上学；go to bed (to sleep) 就寝","go to the church 去教堂；go to the bed 到床跟前去"],"bad":["go to the school（表示“去上学”时不用 the）"]},{"title":"姓氏复数前用 the 表示全家或夫妇","desc":"the + 姓氏复数 = 全家人或这一姓的夫妇二人。","good":["The Taylors were having dinner when I came in.","Don't forget to invite the Greens."],"bad":["Taylors were having dinner when I came in."]}],"contrasts":[{"title":"a/an · the · 零冠词 速判","head":["形式","核心含义","典型例"],"rows":[["a / an","泛指某类中不确定的一个","a tiger is a wild animal；an hour"],["the","特指（独一无二、上文提过、带定语、序数词/最高级/乐器/方位）","the sun；the book I bought；play the piano"],["零冠词","专有名词、物质/抽象名词、复数泛指、三餐/球类/学科/季节、by + 交通工具、平行结构","China；We love peace.；play soccer；by bus；day and night"]]},{"title":"有无冠词含义不同","head":["不用冠词（功能）","用冠词（地点/其他目的）"],"rows":[["go to school 去上学","go to the school 到那所学校去"],["go to church 做礼拜","go to the church 去教堂"],["go to bed 就寝","go to the bed 到床跟前去"]]}],"pitfalls":["判断 a/an 看的是读音不是字母：a university、a European country，但 an hour、an honest boy。","形容词修饰名词时，冠词放在形容词前，a/an 由形容词的读音决定（a bike → an old bike）。","“the + 形容词”表示一类人时，谓语动词用复数：The poor are against the plan.","民间节日前用定冠词（the Spring Festival、the Mid-Autumn Festival），但专有名词、月份、星期前不用冠词。","限定词不能连用：不能说 a his schoolbag / the both schoolbags。"],"examTips":["中考冠词的考查集中在三件事：a 还是 an（看读音）、用不用 the（特指 / 独一无二 / 序数词 / 最高级 / 乐器）、该不该用冠词（三餐、球类、学科、by + 交通工具、固定短语）。","乐器前用 the、球类前不用冠词，是最高频的失分点。"],"memoryCard":["a 辅音音素，an 元音音素；看读音，不看字母。","乐器要加 the，球类不加冠词。","第一次 a，第二次 the。","the poor / the rich 作主语，谓语用复数。"]},"notes":"yufan/冠词 共 13 张全部查看（289—301）。其中 298（Common Mistakes）、299—301（实力测验）为习题页，原书未附答案；本讲义对 Common Mistakes 记录了教材给出的正确解析与答案，对实力测验仅记录考点分布，未编造答案。","sectionCount":11},{"topicId":"g-attributive-clause","newTopic":false,"authored":true,"title":"定语从句","sourceDirs":[],"imagesRead":0,"sourceNote":"依据外研版九年级上册 Module 10 / Module 11 语法聚焦整理","summary":"定语从句放在名词或代词后面起修饰作用：先行词指人用 who/that，指物用 which/that；关系代词作宾语时可省略，作主语时不能省略。","intro":"按教材语法聚焦顺序整理：概念（先行词与关系词）→ that/which 指物（Module 10）→ who/that 指人（Module 11）→ 关系代词作宾语可省略 → 只能用 that 的情形 → 从句中的主谓一致 → 易错清单与辨析。","sectionCount":7},{"topicId":"g-conjunctions","newTopic":false,"title":"连词（讲义精讲）","sourceDirs":["yufan/连词"],"imagesRead":19,"summary":"连词是虚词，起连接词与词、短语与短语、句子与句子的作用，不能独立担任句子成分。本章把并列连词（and/or/but/so/for 及 both...and、either...or、neither...nor、not only...but also、as well as）与从属连词（that、when/while/since、till/until、because、if、though/although、so...that）分开梳理。","intro":"连接并列关系用并列连词，引导从句用从属连词。判断时先看前后两部分是什么关系（并列、转折、因果、选择），再注意两个高频细节：主谓一致的就近原则，以及 because 与 so、though/although 与 but 不能同时出现。","notes":["yufan/连词 目录共 19 张图，已逐张查看：p.148—165（含章节扉页 p.147 的名人名言页）。","p.162—p.165 的「实力测验（Final Check）」为填空/改错/汉译英练习，仅作说明、未逐题转录；讲解性内容已全部提取。","p.153、p.154 的「例」「比较」小框内容已分别转写为 tip 与 table block，个别小框右下角文字在图片边缘被轻微裁切，不影响语义判断。"],"extras":{"forms":[{"name":"并列（和）","pattern":"and","note":"连接对等的词、短语或句子；三个以上并列时 and 放在最后一项前。"},{"name":"选择/否则","pattern":"or","note":"选择；否定句中代替 and；祈使句 + or = If you don't..., you'll..."},{"name":"转折","pattern":"but","note":"前后相反；还可表示「除了……以外」，与 although 不能连用。"},{"name":"因果（结果）","pattern":"so","note":"so 后接结果；也可作副词（I hope so. / Don't walk so fast.）。"},{"name":"因果（说明）","pattern":"for","note":"只用于说明、解释，不用于句首，不能与 because 互换使用场景。"},{"name":"并列短语","pattern":"both...and / either...or / neither...nor / not only...but also","note":"作主语时 either...or、neither...nor、not only...but also 遵循就近原则；both...and 用复数谓语。"},{"name":"从属（时间）","pattern":"when / while / since / after / before / as / as soon as / till / until","note":"主将从现；while 从句谓语需延续性动词；终止性动词与 until 连用要用否定式。"},{"name":"从属（原因/条件/让步/结果）","pattern":"because / if / though / although / so...that","note":"because 不能与 so 连用，though / although 不能与 but 连用。"}],"points":[{"title":"祈使句 + and / or","desc":"祈使句 + and 相当于 If you..., you'll...；祈使句 + or 相当于 If you don't..., you'll...。","good":["Use your head, and you'll find a way. = If you use your head, you'll find a way.","Hurry up, or you'll miss the bus. = If you don't hurry up, you'll miss the bus."],"bad":[]},{"title":"否定句中并列用 or 代替 and","desc":"在否定句中连接并列成分要用 or。","good":["He never smokes or drinks.","The baby is only one year old, so he can't speak or write."],"bad":["The baby is only one year old, so he can't speak and write."]},{"title":"neither...nor 本身是全否定","desc":"neither...nor 已含否定意义，不能再加 not。","good":["Neither you nor I am right."],"bad":["Neither you nor I am not right."]},{"title":"because 与 so 不能同时出现","desc":"汉语的「因为……所以……」在英语中只能选一个连词。","good":["Because he was tired, he couldn't walk there."],"bad":["Because he was tired, so he couldn't walk there."]},{"title":"though / although 与 but 不能同时出现","desc":"用了 though 或 although（虽然），就不能再用 but（但是）。","good":["Though I was tired, I still worked hard.","I live near the sea, but I'm not a good swimmer."],"bad":["Though I was tired, but I still worked hard."]},{"title":"not only...but also 与 as well as 的主谓一致","desc":"not only...but also 的谓语随 but also 后的主语而定；as well as 的谓语随其前面的主语而定。","good":["Not only Mr Lin but also his parents are going to the party.","Mr Lin as well as his parents is going to the party."],"bad":[]}],"contrasts":[{"title":"for 与 because","head":["连词","作用","例句"],"rows":[["for","只表示说明、解释（从现象推断结果），不用于句首","The sun has risen, for the birds are singing."],["because","解释原因、动机，强调因果关系，可回答 why","Why shouldn't I come? — Because you're too busy."]]},{"title":"both...and / either...or / neither...nor 的肯否转换","head":["句型","含义","例句"],"rows":[["I like both A and B.","两者都喜欢","I like both coffee and tea."],["I don't like both A and B. = I like either A or B.","只喜欢其中之一","I like either coffee or tea."],["I don't like either A or B. = I like neither A nor B.","两者都不喜欢","I like neither coffee nor tea."]]}],"pitfalls":["not only...but also 作主语时谓语随 but also 后的主语而定；as well as 作主语时谓语随其前面的主语而定（Not only Mr Lin but also his parents are... / Mr Lin as well as his parents is...）。","both...and 的否定句是部分否定：Both Li Ming and Li Li are not good students. 意为「不都是好学生」。","either...or 的否定句是完全否定；neither...nor 本身已是全否定，不能再加 not。","either...or、neither...nor 中 or / nor 前后的词性必须一致（名词 + 名词、代词主格 + 代词主格、动词 + 动词）。","while 引导的从句谓语只能用延续性动词，不能用 begin、stop 等终止性动词。","since 引导的时间状语从句用过去时，主句一般要用现在完成时。","that 引导的宾语从句中，主句是过去时则从句也要用过去时（时态呼应）；think / believe 等第一人称主句变否定句时要否定主句、译成汉语时否定从句。","在否定句中连接并列成分要用 or 代替 and。","till / until 与终止性动词连用时要用否定式，译成「直到……才……」。"],"examTips":["连词是中考单项填空的固定考点：先判断空前后两句话是并列、转折、因果还是选择关系，再选词。","涉及 both...and / either...or / neither...nor / not only...but also 作主语时，先看谓语是单数还是复数，用就近原则反推连词。","「不能同时用」是高频陷阱：because...so... 与 though/although...but... 都是典型错误选项。"],"memoryCard":["and 顺，or 选（否定用 or），but 转，so 果，for 说明。","祈使句 + and = 就会……；祈使句 + or = 否则……。","both...and 用复数；either...or / neither...nor / not only...but also 就近原则。","because 与 so 不同现，though / although 与 but 不同现。","主将从现：主句将来时，时间/条件状语从句用一般现在时。","延续性动词 + until 用肯定式，终止性动词 + until 用否定式。"]},"sectionCount":8},{"topicId":"g-future-tense","newTopic":true,"title":"动词的将来时","category":"动词","difficulty":3,"sourceDirs":["yufan/动词/动词时态/将来时"],"imagesRead":15,"summary":"将来时用 will / shall + 动词原形表示将来要发生的动作或状态；be going to 强调打算、计划；过去将来时用 would / should + 动词原形，多用于宾语从句和间接引语。","intro":"本章（教材第 14 章，P253—P267）先讲一般将来时的构成与基本用法，再讲过去将来时，最后汇总其他表示将来的结构（be going to / be to do / be about to do、一般现在时与进行时表将来），并附易错陷阱与实力测验。","forms":[{"name":"一般将来时·肯定","pattern":"主语 + will / shall + 动词原形 + ……","note":"I will call you this evening."},{"name":"一般将来时·否定","pattern":"主语 + will / shall + not + 动词原形 + ……","note":"will not 常缩写为 won't。"},{"name":"一般将来时·疑问","pattern":"Will / Shall + 主语 + 动词原形 + ……?","note":"Will there be less pollution?"},{"name":"过去将来时","pattern":"主语 + would / should + 动词原形 + ……","note":"把 will / shall 变为过去式即可，多用于宾语从句和间接引语。"},{"name":"be going to 结构","pattern":"主语 + be going to + 动词原形 + ……","note":"表示打算、计划或决定要做的事，也用于有迹象的预测。"},{"name":"be to do / be about to do","pattern":"be to do sth. / be about to do sth.","note":"表示安排、计划；be about to 表示马上、很快就要发生。"}],"points":[{"title":"一般将来时的基本用法","desc":"表示将来某个时间要发生的动作或存在的状态，常与 tomorrow、next year、soon 等时间状语连用；也可用在主从复合句的主句中。","good":["My mother will spend her holiday in Shanghai in August.","We'll have a picnic if it doesn't rain tomorrow.","I'll send a message to you as soon as I get there."],"bad":["We'll have a picnic if it doesn't rain tomorrow.（从句不能用 will rain）"]},{"title":"主将从现","desc":"在时间状语从句和条件状语从句中，主句用一般将来时，从句要用一般现在时（有时用现在完成时）表示将来。","good":["I'll write a composition about the play after I have seen it.","We'll help him if he asks us."],"bad":["If you will go there, I will go with you."]},{"title":"be going to 与 will / shall 的区别","desc":"be going to 表示主观上事先打算、计划或意图；will / shall 表示未经事先考虑的意图。不清楚是否事先考虑时，两者都可以用。","good":["There is somebody at the door. I'll go and open it.","He is going to change his job."],"bad":["There is somebody at the door. I am going to open it.（未经事先考虑，宜用 I'll）"]},{"title":"过去将来时用于宾语从句和间接引语","desc":"过去将来时表示从过去的某一时间来看将来要发生的动作或状态，也可表示过去习惯性的动作或状态（此时所有人称一律用 would）。","good":["He said he would work for that boss the next year.","Whenever he had time, he would do some reading.","I would play with him when I was a child."],"bad":[]}],"pitfalls":["条件状语从句和时间状语从句中不能用将来时，要改用一般现在时（主将从现）。","对一般疑问句的肯定回答要用 Yes, I will.，不能用缩略式 I'll，因为 shall / will 在句末时不能用缩略式。","There is going to be... 与 There will be... 都表示将来，不能写成 There will have...。","if 既可引导宾语从句（可用一般将来时），又可引导条件状语从句（用一般现在时），两种时态不同。","按时刻表发生的动作（火车发车、飞机起飞等）用一般现在时表将来；go、come、leave、start 等可用现在进行时表将来。"],"examTips":["看到 tomorrow、next week、in the future、soon 等时间状语，优先考虑一般将来时。","答语中出现 right now、now 等提示“临时决定”的词，用 will 而不用 be going to。","看到 if 从句，先判断是宾语从句还是条件状语从句：条件句用一般现在时，主句用一般将来时。","There be 句型的将来时用 There will be / There is going to be，注意不能出现 have。"],"memoryCard":["一般将来时 = will / shall + 动词原形；过去将来时 = would / should + 动词原形。","主将从现：主句将来时，从句现在时。","事先打算用 be going to，临时决定用 will。"],"sectionCount":6},{"topicId":"g-inversion","newTopic":true,"title":"倒装句","category":"句法","difficulty":4,"sourceDirs":["yufan/倒装句"],"imagesRead":7,"summary":"倒装是把谓语的全部或一部分提到主语之前：全部提前叫完全倒装，只把助动词、系动词或情态动词提前叫部分倒装；多为语法结构需要或为了强调。","intro":"按教材第 24 章顺序整理：倒装概述 → 倒装的应用（完全倒装 / 部分倒装 / 让步状语从句 / 虚拟语气 / 感叹句 / so...that / 直接引语 / there be / 修辞倒装）→ 章末常见失分陷阱。","notes":"第 7 张（微信图片_20260927175455_650_66.jpg）为章末「实力测验」选择填空 10 题，原书未附答案，未录入正文。","forms":[{"name":"完全倒装","pattern":"状语（here / there / away... ）+ 谓语 + 主语","note":"谓语通常是 be、go、come、seem、follow；主语为人称代词时不倒装。"},{"name":"部分倒装（否定词开头）","pattern":"否定词（never / seldom / hardly / not / neither / nor / little）+ 助动词 / 系动词 / 情态动词 + 主语 + 谓语","note":"用于语法结构需要或强调。"},{"name":"So / Neither / Nor 引起倒装","pattern":"肯定：So + 助动词 + 主语；否定：Neither / Nor + 助动词 + 主语","note":"表示前面的内容也适用于后面的人或物。"},{"name":"Only + 状语置于句首","pattern":"Only + 副词 / 介词短语 / 状语从句 + 助动词 + 主语","note":"only 修饰主语时不倒装。"},{"name":"让步状语从句倒装","pattern":"表语（名词 / 形容词 / 副词）+ as + 主语 + 系动词","note":"用 as 代替 although；名词作表语时前面不加冠词。"},{"name":"虚拟语气省略 if","pattern":"Should / Had / Were + 主语 + ...","note":"用于省略 if 的虚拟条件句，一般表达与事实相反的情况。"},{"name":"so / such...that 置于句首","pattern":"So + 副词 / 形容词 + 助动词 + 主语 + that...","note":"so 或 such 位于句首时主句要用倒装语序。"}],"points":[{"title":"完全倒装与部分倒装的判断","desc":"句首是方向 / 地点副词或介词短语作地点状语（here、there、away、in the middle of...）时用完全倒装；句首是否定词、only + 状语、so / neither / nor 时用部分倒装。","good":["Here comes the bus.","In the middle of the lake lies a small island.","Never have I been there before.","Only in this way can you work out the problem."],"bad":["Never I have been there before.","Only in this way you can work out the problem."]},{"title":"主语是代词时不倒装","desc":"完全倒装句型中主语若是人称代词，语序保持不变。","good":["Here it is.","Away he went.","At the foot of the mountain it stands."],"bad":["Here is it.","At the foot of the mountain stands it."]},{"title":"so / neither / nor 只表示「也一样」时倒装","desc":"表示「前面的情况也适用于后面的人或物」时用倒装，且时态、助动词要与前句一致。","good":["You can go surfing, so can I.","I have never been abroad, neither has he.","I didn't go to the cinema last night, nor did he."],"bad":["You can go surfing, so I can.","I didn't go to the cinema last night, nor did he did."]},{"title":"as 引导让步状语从句的倒装结构","desc":"把名词 / 形容词 / 副词 / 动词原形提到 as 前面，as 意为「虽然」；名词作表语时前面不加冠词。","good":["Old as he is, he works hard.","Child as he is, he knows a lot.","Strange as it might sound, his idea was accepted."],"bad":["A child as he is, he knows a lot.","As strange it might sound, his idea was accepted."]}],"contrasts":[{"title":"完全倒装 vs 部分倒装","head":["比较项","完全倒装","部分倒装"],"rows":[["倒装范围","整个谓语置于主语之前","只把助动词 / 系动词 / 情态动词提前"],["常见触发","here / there / now / then / up / down / out / in / away 开头；地点状语介词短语置于句首","否定词开头、so / neither / nor、only + 状语、so...that、修辞性倒装"],["例句","Here comes the bus.","Never have I been there before."]]},{"title":"so / neither / nor 的呼应","head":["前句","后句结构","例句"],"rows":[["肯定句","So + 助动词 + 主语","You can go surfing, so can I."],["否定句","Neither / Nor + 助动词 + 主语","I have never been abroad, neither has he."],["否定句","Nor + 助动词 + 主语","I didn't go to the cinema last night, nor did he."]]}],"pitfalls":["否定词或 only + 状语置于句首时才倒装；only 修饰主语时不倒装：Only Amanda and John received my presents.","完全倒装中主语是人称代词时不倒装：Here it is. / Away he went.","让步状语从句用 as 时要把表语提前，且名词作表语时不加冠词：Child as he is...","as 引导让步状语从句的结构是「名词 / 形容词 / 副词 / 动词原形 + as + 主语 + 系动词」，不是 as 直接置于句首：Strange as it might sound。","so / neither / nor 引起的倒装，助动词的时态和形式要与前一句保持一致：My room gets very cold. — So does mine.","否定词开头的部分倒装，语序为「否定词 + 助动词 / 情态动词 + 主语 + 其他」：Not until... did he stop..."],"examTips":["中考单选常以「否定词 / only + 状语 / so + 倒装 / as 让步倒装 / not until」为主要考法，先找句首的触发词，再判断完全还是部分倒装。","看到句首是 here、there、away、in the middle of... 时判断主语是不是人称代词；是代词就不倒装。","so / neither / nor 呼应句要与前句的时态、助动词一致，前句是实义动词一般现在时（gets），后句用 does。","Not until 置于句首时，倒装发生在主句：Not until the motorbike looked almost new did he stop repairing and cleaning it."],"memoryCard":["谓语全部提前 = 完全倒装；只提前助动词 / 系动词 / 情态动词 = 部分倒装。","here / there / away + 名词主语才倒装，代词主语不倒装。","否定词、only + 状语在句首，都要部分倒装。","让步从句：表语 + as + 主语（Child as he is...）。","省略 if 的虚拟：Should / Had / Were 提前。","so / neither / nor 呼应倒装，助动词要跟前句一致。"],"sectionCount":6},{"topicId":"g-modal-verbs","newTopic":false,"title":"助动词和情态动词","sourceDirs":["yufan/动词/助动词和情态动词"],"imagesRead":21,"summary":"助动词 be / have / shall·will / do 本身没有词义，只帮助主要动词构成时态、语态、否定与疑问；情态动词 can、may、must、need、should、ought to、had better、have to 等有词义但不能单独作谓语，后面跟动词原形（ought to 除外），没有人称和数的变化。","intro":"本章先讲助动词的种类与作用，再按 can(could)、may(might)、must、need、should/ought to/had better、have to 依次讲情态动词的肯定句、否定句、疑问句与回答，最后归纳 can/could/may/might/must 表示推测（含对过去的推测 must have done）以及 Will you / Would you like / Shall I / Shall we 等句型。","extras":{"forms":[{"name":"can / could 与 be able to","pattern":"can / could + 动词原形；be able to 可用于各种时态","note":"can 只有现在式 can 和过去式 could，其他时态用 be able to：He has been able to make a homepage and shop online. / Perhaps people will be able to live on the moon in the future."},{"name":"must 的疑问句与回答","pattern":"Must + 主语 + 动词原形...? Yes, ...must. / No, ...needn't. / ...don't have to.","note":"以 must 提问时，否定回答用 needn't 或 don't have to，不用 mustn't。"},{"name":"must / may / might + have done","pattern":"must / may / might + have + 过去分词","note":"表示对过去的状态、动作的肯定推测：It must have rained last night. / She may have missed the bus."},{"name":"can / could + not + have done","pattern":"can't / couldn't + have + 过去分词","note":"表示对过去的否定推测：He can't have forgotten. / It can't have rained last night."},{"name":"can / could / may / might / must + be + doing","pattern":"对现在及将来正在发生的动作进行推测","note":"She may / might be enjoying the sunshine on the lawn."},{"name":"should / ought to","pattern":"should + 动词原形；ought to + 动词原形","note":"ought to 语气比 should 更强烈，是唯一带不定式 to 的情态动词。"},{"name":"had better","pattern":"had better + 动词原形；否定：had better not + 动词原形","note":"只有一种形式，没有 have / has better 这类形式。"},{"name":"have to 的时态变化","pattern":"have / has to → had to → will have to；否定 don't / doesn't / didn't / won't have to","note":"主语为第三人称单数用 has to；疑问句用 Do / Does / Did / Will + 主语 + have to...?"},{"name":"Will you / Would you (like) / Shall I / Shall we","pattern":"Will you (please) + 动词原形...? / Would you (like) + 动词原形...? / Shall I / we + 动词原形...?","note":"Would you 比 Will you 更婉转；“Would you like...” 表示“你想/愿意……吗？”；Shall I 提出建议，Shall we 提出建议或邀请。"}],"points":[{"title":"must 与 have to 的区别：主观必要 vs 客观必要","desc":"must 侧重于个人意愿和主观上的必要；have to 侧重于客观上的必要。must 只有一种形式，have to 有较多形式、可用于各种时态，must 用于过去时或将来时要用 have to 代替；must 也可用于间接引语中表示过去的必要或义务。","good":["I know I must study hard.","The last bus has gone. We have to take a taxi.","My brother was badly ill, so I had to call the doctor at midnight.","He said that they must work hard."],"bad":["My brother was badly ill, so I must call the doctor at midnight at that time."]},{"title":"can / could / may / might / must 表示推测的程度不同","desc":"may / might 表示“有可能；大概”，might 比 may 弱，相当于 perhaps；can / could 表示“或许”，可能性比 may / might 小，相当于 possibly；must 可能性最强，语气较肯定，一般只用于肯定句。","good":["She must be out.","The news could be true.","The earrings might be a present for her mother.","Monica can't be in the classroom."],"bad":["She mustn't be out.（表示“肯定不在”，应用 can't be out）"]},{"title":"need 的情态动词与行为动词用法","desc":"need 意为“需要”，作情态动词时主要用于否定句和疑问句（needn't / Need I...?），作行为动词时可用于肯定句、否定句和疑问句（needs to do / Do you need...?），还可用在反意疑问句中，前后保持一致。","good":["You needn't finish that work today.","Do you need any help?","I guess Anna just needs to talk to somebody sometimes.","We needn't wait too long, need we?"],"bad":["You don't need finish that work today.= You don't need to finish that work today."]},{"title":"请求与征求对方意见的句型","desc":"Will you...? 请（为我）做某事好吗；Would you...? 可以请你……吗（更婉转）；Would you like...? 你想要……吗（用于请人吃东西、征询意见或询问意向）；Shall I...? 我要……吗（提出建议）；Shall we...? 我们一起做……好吗（提出建议、邀请）。","good":["Will you please take off your hat?","Would you tell me the way to the Exhibition Centre?","Would you like to chat with me at lunch time?","Shall I wind the car window down?","Shall we take a boat together now?"],"bad":["Will you please to take off your hat?"]}],"contrasts":[{"title":"must vs have to","head":["对比项","must","have to"],"rows":[["必要性来源","主观上的必要（个人意愿）","客观上的必要（客观情况）"],["形式","只有一种形式","有较多形式，可用于各种时态"],["过去/将来","用于间接引语中表示过去的必要或义务","一般过去时用 had to；一般将来时用 will have to"],["否定含义","mustn't 不可以、禁止","don't have to 不必（没有必要）"]]},{"title":"can / could vs be able to","head":["对比项","can / could","be able to"],"rows":[["时态","只有现在式 can 和过去式 could","可用于各种时态"],["表示能力","I can use the microwave oven and the toaster.","I could send e-cards before having the computer lessons.（过去时）"],["现在完成时","×","He has been able to make a homepage and shop online."],["将来时","×","Perhaps people will be able to live on the moon in the future."]]},{"title":"对现在/将来的推测 vs 对过去的推测","head":["时间","结构","例句"],"rows":[["现在/将来（状态、动作）","can / could / may / might / must + 动词原形","She must be out. / The news could be true."],["现在/将来（正在发生）","can / could / may / might / must + be + doing","She may / might be enjoying the sunshine on the lawn."],["过去（肯定推测）","must / may / might + have + 过去分词","It must have rained last night. / She may have missed the bus."],["过去（否定推测）","can / could + not + have + 过去分词","He can't have forgotten. / It can't have rained last night."]]}],"pitfalls":["以 must 提问的一般疑问句，否定回答用 needn't 或 don't have to，不能用 mustn't（mustn't 表示禁止）。","can't 表示“不能/不可能”，mustn't 表示“不允许（禁止）”，shouldn't 表示“不应该”，三者不能混用。","must 表推测一般只用于肯定句；表示“肯定不/不可能”要用 can't。","had better 后跟动词原形（had better do），不能说 had better to do；no better 形式变化（没有 have better / has better）。","ought to 是唯一带 to 的情态动词，其否定式是 ought not to do。","will / would 后接动词原形：Will you please to pass me the dictionary? 是错的（应用 pass）。","used to 与 be used to 不同；don't have to 表示“不必”，mustn't 表示“禁止”。"],"examTips":["看到 Must I...? / Must I...? 的否定回答，优先选 needn't 或 don't have to。","看到表示请求许可的语境，can / may / could 均可，但 can 不如 may 正式，could 更客气（不表示过去）。","看到“还不确定、可能”的语境选 may；看到“肯定、准是”选 must；看到“绝不可能”选 can't。","看到 yesterday / last night 等过去时间且表示推测，用 must have done / may have done / can't have done。","看到 it ______ work 这类助动词时态填空，先看时间状语再定时态（如 but it doesn't work 表现在的状态）。"],"memoryCard":["助动词无词义：be 进行/被动，have 完成，will/shall 将来，do 否定疑问。","情态动词后跟原形，没有人称和数的变化（ought to 除外）。","must 提问，needn't 回答。","must 主观，have to 客观；mustn't 禁止，needn't 不必。","may / might 可能，could 也许，must 一定；对过去用 have done。"]},"notes":["第186页（can/may/must/need 基本句型页）拍摄时整体旋转 90°，文字清晰可辨，已按可识别内容完整转写。","第201—203页“实力测验”的答案栏在教材原图中为空白，只转写题型与考点，未编造答案。"],"sectionCount":8},{"topicId":"g-nonfinite-verbs","newTopic":true,"title":"非谓语动词","category":"动词","difficulty":4,"sourceDirs":["yufan/动词/非谓语动词"],"imagesRead":17,"summary":"非谓语动词包括动词不定式（to do）、动词-ing 形式（现在分词与动名词）和过去分词（done）三种。它们没有人称和数的变化，不受主语人称和谓语动词时态的干扰，但不能单独作谓语，仍保留动词特点（可带自己的宾语和状语）。","intro":"本章分三块：动词不定式的类型、句法功能、时态语态与重要句型；动词-ing 形式作主语、宾语、表语、宾语补足语、定语、状语；过去分词作定语、表语、宾语补足语、状语（含与被动语态、定语从句的区分），最后是中考易错陷阱与实力测验。","forms":[{"name":"动词不定式·一般式","pattern":"to + 动词原形","note":"不定式的动作发生在谓语动作之后，或与谓语动作同时发生。"},{"name":"动词不定式·否定式","pattern":"not to + 动词原形","note":"否定需在 to 前加 not：Mum often tells Tom not to play football in the street."},{"name":"动词不定式·完成式","pattern":"to have + 过去分词","note":"表示不定式的动作发生在谓语的动作之前：I am sorry to have kept you waiting for a long time."},{"name":"动词不定式·进行式","pattern":"to be + 现在分词","note":"表示不定式的动作与谓语的动作同时进行：He seems to be worrying about it."},{"name":"动词不定式·被动语态","pattern":"to be + 过去分词","note":"表示被动关系：The sick man will need to be taken to a hospital."},{"name":"疑问词 + 动词不定式","pattern":"疑问词 + to + 动词原形","note":"常可与宾语从句互换：I don't know what to do. = I don't know what I should do."},{"name":"动词-ing 形式","pattern":"动词原形 + -ing","note":"包括现在分词和动名词两种，可作主语、宾语、表语、宾语补足语、定语、状语。"},{"name":"过去分词","pattern":"动词 + -ed（不规则动词需逐一记忆）","note":"可作定语、表语、宾语补足语、状语，表示被动或完成。"},{"name":"省略 to 的不定式","pattern":"make / let / have / see / hear / watch / feel / notice / listen to + 宾语 + 动词原形","note":"口诀：一感二听三让四观看；用于被动语态时被省略的 to 要还原。"}],"points":[{"title":"不定式作主语时常用形式主语 it","desc":"带 to 的不定式作主语时，常用形式主语 it 代替，其作表语的形容词有 important、easy、difficult、hard、good、bad、right 等。","good":["To learn a foreign language is not easy.","It is too hard for him to work out such a difficult problem.","It's useless arguing with him."],"bad":["It is too hard for him work out such a difficult problem."]},{"title":"感官动词与使役动词后的不定式省略 to（被动要还原）","desc":"make、let、have 等使役动词和 hear、see、notice 等感官动词后的不定式省略 to；但用于被动语态时，被省略的 to 需要还原。口诀：一感 feel；二听 hear, listen to；三让 let, have, make；四观看 observe, see, watch, look at。","good":["The boss made Tom's father work all day.","I saw him go into the classroom just now.","He was made to do the job at once."],"bad":["He was made do the job at once.","I saw him to go into the classroom just now."]},{"title":"只接 -ing 作宾语的动词与只接不定式的动词要分清","desc":"enjoy、finish、mind、practise、keep、consider、miss、avoid、suggest、give up、put off、cannot help 等只能接动词-ing 形式作宾语；want、hope、wish、agree、decide、manage、refuse、pretend 等只接不定式作宾语。","good":["Good news keeps on coming.","I am considering selling my house to collect money.","He wants to buy some stamps."],"bad":["I am considering to sell my house to collect money."]},{"title":"remember / forget / stop 等接 to do 与 -ing 意思不同","desc":"有些动词（短语）既能接动词-ing 形式，又能接不定式作宾语，但意义不一样：remember、forget 等后接不定式时表动作尚未发生，接动词-ing 形式时表动作已经完成；like、love、hate、start、begin、need、go on、try 等前后意义区别较大（前者没有多大区别）。","good":["Oh, I forgot to turn it off.（忘记去做，还没做）","I remembered closing the door.（记得做过）","Mr Brown asked us to stop talking, and we stopped to listen to him at once."],"bad":["I forgot turning it off 用于“我忘了是关过灯的”这个意思之外会造成歧义。"]},{"title":"过去分词作表语与被动语态的区别","desc":"过去分词作表语表示主语的特点或所处的状态，被动语态则表示一个被动的动作；过去分词作表语还可用于 get、become、grow、turn 等词后面，而被动语态没有此种用法。","good":["The cup is broken.（过去分词表状态）","The cup was broken by my brother.（被动语态表动作）","We became / got excited.","We were excited by the news."],"bad":["We became / got excited by the news."]},{"title":"have / get + 宾语 + 过去分词表示“让别人做某事”或“遭遇”","desc":"使役动词 keep、leave、get、make 的宾语后面常带过去分词作宾语补足语，表示“使……处于某种状态”，分词和宾语之间是被动关系。","good":["I must have my hair cut tomorrow.","Mary got the car washed.","Jane had her purse stolen on the bus yesterday.","We mustn't leave the work unfinished."],"bad":["I must have my hair cut tomorrow 若写成 I must cut my hair 则意为自己剪，含义不同。"]}],"pitfalls":["感官动词、使役动词后省略 to，但在被动语态中必须还原 to：He was made to do the job at once.","不定式的否定式是在 to 前面加 not（not to do），不能说 don't to do。","只能接动词-ing 形式作宾语的动词（enjoy、finish、mind、practise、keep、consider、avoid、cannot help 等）后不能接不定式。","不定式作定语或状语时，若不定式是不及物动词，或所修饰的名词是不定式动作的地点、工具，必须加上相应的介词：a big room to live in、a knife to cut the bread with、The pen is good to write with.","be dressed in 表示“某人穿着（某种颜色）衣服”，dress 作及物动词后接人；Dressed in a white uniform, he looks more like a cook than a doctor.","过去分词作状语时，其逻辑主语必须与主句主语一致，且为被动关系；连词 + 分词是状语从句的省略形式（When completed = When the museum is completed）。","过去分词与现在分词作定语、状语时要分清主动与被动、进行与完成：The dancing girl（主动进行）vs a broken window（被动完成）。"],"examTips":["感官动词后接 -ing 表示动作正在进行，接不带 to 的不定式表示动作的全过程：I heard Mum talking with Dad at ten last night.（那一刻正在）","forget / remember / stop / go on / try 后用 to do 还是 -ing 是中考高频考点：前者表未做，后者表已做。","It is + 形容词 + of sb to do sth（形容人的品格）与 It is + 形容词 + for sb to do sth（形容事情）要会选：It is necessary for us to protect wildlife.","定语位置要判断：time allowed（= that had been allowed）用过去分词；the meeting to attend 用不定式。","can't help doing（禁不住）与 can't help but do（不得不）要区分。"],"memoryCard":["非谓语三兄弟：to do（不定式）、doing（-ing 形式）、done（过去分词）。","非谓语不能单独作谓语，但可带自己的宾语和状语。","一感二听三让四观看，后省 to；被动还原 to。","疑问词 + to do 常可改写成宾语从句。","过去分词 = 被动 + 完成；现在分词 = 主动 + 进行。"],"notes":["第304—319页均为清晰的教材正文页；第316—319页“实力测验”的答案栏为空白，只转写题型与考点，未编造答案。"],"sectionCount":8},{"topicId":"g-nouns","newTopic":false,"title":"名词与主谓一致","sourceDirs":["yufan/名词"],"imagesRead":15,"summary":"名词先按「专有 / 普通」两分，普通名词再分个体、集体、物质、抽象四类；讲义按「种类 → 数 → 量 → 所有格 → 句法功能」五步系统展开。","intro":"教材第 1 章·名词用四个部分讲名词：一、名词的种类；二、名词的数（可数名词和不可数名词）；三、名词的所有格（构成及用法）；四、名词的用法。以下按图片原顺序整理为讲义。","notes":"第 13—15 张（微信图片_20260927085022_255_66.jpg / 微信图片_20260927085051_256_66.jpg / 微信图片_20260927085100_257_66.jpg）为章末「实力测验 Final Check」练习页（用括号中名词的适当形式填空、用括号中适当的词填空、改错、选择填空），原书未附答案，未录入正文。","extras":{"forms":[{"name":"名词所有格（'s / '）","pattern":"单数名词 + 's；已有复数词尾的名词 + '","note":"Tom's cap；the workers' struggle；并列名词共有只在最后一个后加 's。"},{"name":"复合名词复数","pattern":"主体名词变复数（passer-by→passers-by）；man / woman 构成的复合名词两个词都变（man doctor→men doctors）","note":"没有主体名词时，复数词尾加在最后一个词上。"},{"name":"不可数名词的确切数量","pattern":"a / an / 数词 + 单位词 + of + 不可数名词","note":"a glass of water；two bags of rice；单位词随数量变成复数。"},{"name":"名词作定语","pattern":"名词 + 名词","note":"colour TV、gold chain、history lesson、rain drops；与形容词作定语（colourful flowers、golden fish）区分。"}],"points":[{"title":"a / an 看紧跟其后的词的首音","desc":"a / an 后面若接「形容词 + 单数名词」，判断用 a 还是 an 要看紧跟的形容词开头字母的发音，而不是看名词。","good":["a fresh orange","an impolite soldier"],"bad":["an fresh orange","a impolite soldier"]},{"title":"以 s 结尾并不等于复数","desc":"maths、physics、politics、means、goods、works 等虽以 s 结尾，但是单词本身词尾为 s，应作单数看待。","good":["Physics is very difficult for me."],"bad":["Physics are very difficult for me."]},{"title":"只有复数形式的名词要借单位词计数","desc":"trousers、clothes、glasses、scissors 等只有复数形式，不能直接加 a / an 或数词，要用「数词 + 单位词 + of」。","good":["I want to buy two pairs of trousers."],"bad":["I want to buy two trousers."]},{"title":"并列名词所有格：共有还是各自所有","desc":"表示各自所属时，两个名词之后都要加 's；表示共同所属时，只在最后一个名词之后加 's。","good":["This is Tom and his brother's room.（两人共有一个房间）","These are Tom's and his brother's rooms.（两人有各自的房间）"],"bad":[]}],"contrasts":[{"title":"修饰可数名词复数与不可数名词的词","head":["修饰可数名词复数","修饰不可数名词"],"rows":[["some","not (any) / no"],["(a) few","little"],["many","a little / some"],["a lot of / lots of / plenty of","much / a great deal of"]]}],"pitfalls":["a / an 的选择要看紧跟其后的形容词首音：a fresh orange（√）、an impolite soldier（√）。","handkerchief 有两种复数形式：handkerchiefs / handkerchieves。","clothes、glasses、scissors、trousers 等只有复数形式，不能用 a / an 或数词直接修饰，要用 a pair of 之类单位词。","并列名词所有格要辨清「共有」还是「各自所有」：Tom and his brother's room 指两人共有一个房间。","由普通名词构成的专有名词要加 the（the Great Wall、the White House），但首字母不大写。"],"examTips":["名词所有格与不可数名词是本章两个高频陷阱：看到「几分钟 / 几天的路程」用 minutes' / days' walk；看到 advice、information、room（空间）先判定为不可数。","「名词 + 名词」作定语的固定搭配（income tax、the city centre、a goods train）常在完形与语篇题中出现，不要按汉语语序改写。"],"memoryCard":["a / an 看紧跟词的音，不看名词本身。","f / fe 变复数：多数变 v 加 -es，belief / roof / chief / safe 直接加 -s。","以 s 结尾不等于复数：maths、physics、politics 作单数。","无生命物表所属以 of 结构为主；时间、距离、国家、城市可用 's。"]},"sectionCount":11},{"topicId":"g-numerals","newTopic":false,"title":"数词","sourceDirs":["yufan/数词"],"imagesRead":9,"summary":"数词分基数词与序数词：表示数目多少的叫基数词，表示顺序次序的叫序数词；数词的用法相当于名词或形容词。","intro":"数词既有名词性质，又有形容词性质：相当于名词时在句中作主语、表语、宾语；相当于形容词时在句中作定语；基数词还能作同位语。","extras":{"forms":[{"name":"基数词整十位","pattern":"20—90 以 -ty 结尾；21—99 十位与个位之间加连字符","note":"twenty, thirty, twenty-one, forty-five"},{"name":"基数词三位数及以上","pattern":"百位与十位之间加 and；1000 以上每三位加逗号，thousand / million","note":"one hundred and fifty-six；two thousand (and) eight"},{"name":"序数词构成","pattern":"4—19 加 -th；整十位 -ty 改 -tieth；其他只把个位数改成序数词","note":"fifth, eighth, ninth, twelfth, twentieth, thirty-first"},{"name":"序数词缩写","pattern":"1st / 2nd / 3rd / 11th / 21st / 32nd / 44th / 63rd","note":"1、2、3 用 st/nd/rd，其余用 th"},{"name":"每逢 / 每隔","pattern":"every + 序数词 + 单数名词 = every + 基数词 + 复数名词","note":"every second day = every two days"}],"points":[{"title":"基数词可作同位语","desc":"数词作同位语只限基数词，用来补充说明前面的代词或名词。","good":["We two will go with you.","Can you help us three with our maths?"],"bad":["We second will go with you."]},{"title":"“a + 序数词”表示再一次","desc":"序数词前有时加不定冠词 a，表示再一次，相当于 again。","good":["He wants to try a second time. = He wants to try again."],"bad":["He wants to try the second time.（表再一次时不用 the）"]},{"title":"another / more 修饰数词的位置","desc":"another 修饰数词时放在数词前；more 修饰数词时放在数词之后；数词后的名词用复数。","good":["another two hours","two more hours"],"bad":["two another hours","more two hours"]}],"contrasts":[{"title":"数字在前 vs 数字在后","head":["表达","规则","例"],"rows":[["数字在前","用序数词","the first picture（第一幅画）"],["数字在后","用基数词","page twenty（第 20 页）"]]},{"title":"确定数目 vs 泛指","head":["形式","含义","例"],"rows":[["hundred/thousand/million（单数）","确定数目","two hundred students"],["hundreds/thousands/millions + of","不确切数目","thousands of stars"]]}],"pitfalls":["小数、分数读法：小数点读 point，小数点后逐位读基数词；分数“分子基数词 + 分母序数词”，分子超过 1 分母加 s。","时刻表达：过了半点用 past，未到半点用 to；15 分 a quarter，30 分 a half。","年龄“三十多岁、四十多岁”用 in one's thirties / forties，不能用 in one's thirty。","序数词作定语一般要加 the；但“a + 序数词”表示“再一次”。"],"examTips":["中考对数词的考查集中在：基数词与序数词的区分、hundred/thousand/million 的单复数与 of、分数与百分数、编号与时刻表达。","记住口诀：有数字不加 s，没数字加 s 接 of。"],"memoryCard":["“数字在前用序数，数字在后用基数”：the first picture / page twenty。","数词修饰语位置：another two hours = two more hours。","the ninth / the twelfth / the twentieth 是拼写高危词。"]},"notes":"yufan/数词 共 9 张全部查看（302—310）。其中 309（Common Mistakes）与 310（实力测验）为习题页，原书未附答案，本讲义只客观记录题干考点与解析要点，未编造答案。","sectionCount":12},{"topicId":"g-overview","newTopic":true,"title":"总论","short":"总论","category":"词法","difficulty":1,"sourceDirs":["yufan/总论"],"imagesRead":9,"summary":"总论梳理英语语法的整体框架：十大词类、词形变化、三种构词法（转化/合成/派生）与句子成分，是后续各个专题的“总地图”。","intro":"英语语法是研究英语语言使用规律的一门学科，主要由词法和句法构成；语法可分为词类、词形变化、构词法和句子成分四大部分。","forms":[{"name":"实词 / 虚词","pattern":"实词：名词 n.、形容词 adj.、数词 num.、代词 pron.、动词 v.、副词 adv.；虚词：冠词 art.、介词 prep.、连词 conj.","note":"实词能在句子中独立充当成分，虚词不能。"},{"name":"构词法三种","pattern":"转化（词类转换，词形基本不变）/ 合成（两词以上合为一个词）/ 派生（词根 + 前缀或后缀）","note":"派生：前缀多改变词义，后缀多改变词类。"},{"name":"句子成分","pattern":"主语 + 谓语（+ 表语 / 宾语 / 宾语补足语）+ 定语 / 状语","note":"主语和谓语是句子的主体部分；其余为次要部分。"}],"points":[{"title":"一词多词性，按在句中的功能判断","desc":"同一个词可以是名词也可以是动词；可以是形容词也可以是副词。不要把一个词固定看成某一词类。","good":["Last year he paid a visit to London with his parents.（visit 作名词）","He visits his grandparents once a week.（visit 作动词）","She prefers a fast car to a slow car.（fast 作形容词，修饰 car）","The little boy can run as fast as his elder brother.（fast 作副词，修饰 run）"],"bad":["只看单词拼写判断词性，而不看它在句中的位置和功能。"]},{"title":"合成词变复数：只变主体名词","desc":"多数合成名词变复数时，只把主体名词变成复数；但由 man、woman 构成的合成词变复数时，必须把两个词都变为复数。","good":["daughter(s)-in-law 儿媳；passer(s)-by 过路人","tooth-brush(es) 牙刷；playground(s) 操场","women teachers 女教师；men doctors 男医生"],"bad":["woman teachers（man/woman 构成的合成词须两个词都变复数）"]},{"title":"不定式作主语，常用形式主语 it","desc":"不定式（短语）可以作主语，但常用由形式主语 it 引出的句型，真正的主语仍在后面。","good":["To teach them English is my job.","It is my job to teach them English."],"bad":["把 It is my job to teach them English. 中的 it 当成真正的主语。"]}],"pitfalls":["不要把单词固定在某一词性上：语言是灵活的，要注意掌握单词的词性，才能减少不必要的错误。","合成词变复数一般只变主体名词（daughter(s)-in-law、passer(s)-by）；但 man/woman 构成的合成词要把两个词都变复数（women teachers、men doctors）。","数词和表示年龄、重量、尺寸的名词用连字符构成合成形容词时，这些名词要用单数形式：a five-year-old boy、a four-foot-long box。","感叹词比较特殊，一般不在句子中充当成分；不定式前的 to 是小品词，与介词 to 不同。"],"examTips":["总论是各专题的“地图”：中考不会单独考“总论”，但词性判断、构词法（合成形容词作定语、派生词词义辨析）常穿插在单选、完形与语篇填空中出现。","做题时先判断空格在句中充当什么成分、修饰谁，再决定词性与词形。"],"memoryCard":["十大词类：名、形、数、代、动、副、冠、介、连、叹。","实词可独立充当成分；冠词、介词、连词不能。","构词三法：转化、合成、派生。","句子成分：主、谓、表、宾、宾补、定、状。"],"extras":{"memoryCard":["四大部分：词类、词形变化、构词法、句子成分。","合成词变复数：只变主体名词；man/woman 构成的合成词两个词都变。"]},"notes":"yufan/总论 共 9 张全部查看（234—242）。最后一张（242）为“表语”开头，教材内容在此页截断，后续内容在“句子成分和基本句型”目录中。","sectionCount":13},{"topicId":"g-passive-voice","newTopic":false,"title":"被动语态","sourceDirs":["yufan/动词/被动语态"],"imagesRead":15,"summary":"被动语态由「be 动词 + 过去分词」构成，时态通过 be 的变化体现，共有十种时态形式；主动变被动时，宾语提到句首作主语，原主语用 by 引出。","intro":"本章（教材第 16 章，P287—P301）在现有「被动语态」专题之外，补充了十种时态的被动形式总表、四种句型的被动、主动变被动的完整步骤，以及 SVO / SVOO / SVOC / 短语动词 / 情态动词 / be going to / 祈使句等各类被动结构，并辨析了被动语态与系表结构。","extras":{"forms":[{"name":"现在进行时被动","pattern":"am / is / are + being + 过去分词","note":"A new railway is being built."},{"name":"过去进行时被动","pattern":"was / were + being + 过去分词","note":"The roads were being widened then."},{"name":"现在完成时被动","pattern":"have / has + been + 过去分词","note":"These plants have been grown without the use of any chemicals."},{"name":"过去完成时被动","pattern":"had been + 过去分词","note":"A new hotel had been built when I got there."},{"name":"将来完成时被动","pattern":"will / shall have been + 过去分词","note":"Many new stadiums and gyms will have been built in London by next year."},{"name":"过去将来时被动","pattern":"would / should be + 过去分词","note":"Toby said the new hotel would be built in six months."},{"name":"双宾语被动 (SVOO)","pattern":"The guard was shown the pass. / The pass was shown to the guard.","note":"用直接宾语作主语时，保留的间接宾语前要加 to / for / of 等介词。"},{"name":"be going to 被动","pattern":"be going to be + 过去分词","note":"His email is going to be checked (by him)."},{"name":"祈使句被动","pattern":"Let + 原宾语 + be + 过去分词","note":"Empty the rubbish bin at once! → Let the rubbish bin be emptied at once!"}],"points":[{"title":"双宾语动词的两种被动语态","desc":"间接宾语作被动语态主语时，直接宾语保留在后面；直接宾语作主语时，保留下来的间接宾语前要加 to、for、of 等介词。有些动词习惯上只用某一种改写方式。","good":["The guard was shown the pass (by Lenin).","The pass was shown to the guard (by Lenin).","A skirt was sewed for me by my aunt.（符合习惯）","James was refused a passport by the authorities.（符合习惯）"],"bad":["She was written a letter by him.（不合习惯）","The invitation was refused him by me.（不合习惯）"]},{"title":"含宾语补足语的句子变被动：补足语变主语补足语","desc":"宾语补足语放在过去分词之后，位置不变但功能变成主语补足语；感官动词和使役动词后原本省略的 to 要还原（let 例外）。","good":["We call her a beauty. → She is called a beauty (by us).","He saw a thief steal something from the room. → A thief was seen to steal something from the room."],"bad":[]},{"title":"短语动词的被动语态：介词不能丢","desc":"不及物动词加介词或副词后构成短语动词，相当于及物动词，可以有被动语态；介词位置固定，被动语态中不能省略。","good":["She looks after her grandmother. → Her grandmother is looked after (by her).","A truck is running over a bag. → A bag is being run over (by a truck)."],"bad":["Her grandmother is looked after.（介词 after 不能丢，否则意思完全改变）"]},{"title":"祈使句的被动语态","desc":"肯定祈使句用 Let + 原宾语 + be + 过去分词；否定祈使句用 Don't let + 原宾语 + be + 过去分词。","good":["Empty the rubbish bin at once! → Let the rubbish bin be emptied at once!","Don't tell the truth to him. → Don't let the truth be told to him."],"bad":[]}],"contrasts":[{"title":"被动语态 vs 系表结构","head":["结构","含义","例子"],"rows":[["被动语态","表示以主语为承受者的动作","The letter was written yesterday. / The store was closed at five."],["系表结构","表示主语的特点或所处的状态","The letter is written in English. / The store is closed today."]]}],"pitfalls":["感官动词（see、watch、look at、observe、listen to、hear、feel 等）和使役动词（make、have 等）变被动后，主语补足语前一律加 to；但含 let 的句子变被动时 to 可以省略。","宾语是反身代词（introduce oneself、find oneself）或谓语是表状态的及物动词（have、suit）时，主动语态不能变为被动语态。","双宾语动词变被动时有习惯用法限制：「She was written a letter by him.」「The invitation was refused him by me.」都不合习惯。","由被动语态形成的动词短语（be covered with、be interested in、be made of / from、be surprised at）本身就是被动形式，不需再加 by...。"],"examTips":["先判断主语是动作的执行者还是承受者：物作主语且动作由人发出，基本就是被动。","看到 homework、room 等作主语且需要「完成」，用「情态动词 + be + 过去分词」，如 must be finished。","be allowed to do sth. 意为「被允许做某事」；一般将来时被动语态的否定结构是 will not be + 过去分词。","每次应/每年发生（every year）提示一般现在时；a number of trees 作主语且是动作承受者时用 are planted。"],"memoryCard":["被动 = be + 过去分词；时态看 be，动词用分词。","双宾语被动：人作主语直接跟过去分词，物作主语要加 to / for。","感官、使役动词变被动要还 to（let 例外）；短语动词的介词不能丢。"]},"sectionCount":7},{"topicId":"g-past-simple","newTopic":false,"title":"一般过去时","sourceDirs":["yufan/动词/动词时态/一般过去时"],"imagesRead":15,"summary":"第12章把一般过去时分成 be 动词和行为动词两套：be 动词的过去式是 was/were，行为动词的过去式一般在词尾加 -ed（不规则动词要另记）；否定与疑问由 be 动词或 did 承担，did/didn't 后面一律用动词原形。","intro":"本章依次讲 be 动词的一般过去时、行为动词的一般过去时、一般过去时的基本用法，并给出不规则动词表、一般现在时与一般过去时的句型对比、used to 的用法与中考失分陷阱。","extras":{"forms":[{"name":"be 动词的过去式","pattern":"was / were + ……","note":"I/he/she/it 用 was；you/we/they 用 were。"},{"name":"used to 结构","pattern":"used to do / didn't use to do / Did ... use to do?","note":"强调过去有过、现在已终止的习惯。"}],"points":[{"title":"行为动词一般过去时没有人称和数的变化","desc":"主语即使是第三人称单数，谓语动词也用过去式，不加 -s。","good":["He had a good time yesterday.","She studied Korean two years ago."],"bad":["She studieds Korean two years ago."]},{"title":"used to 强调已经终止的习惯","desc":"used to do 表示过去常做而现在已不做的动作，强调与现在的关系。","good":["Paul used to drink.","I used to take a walk after supper."],"bad":["Did he used to smoke?"]},{"title":"过去连续发生的动作用一般过去时","desc":"往往没有时间状语，要通过上下文判定。","good":["The boy opened his eyes for a moment, looked at the captain, and then died.","Joe was late. He dressed himself quickly, rushed out of the house and ran to the school."],"bad":[]},{"title":"过去时可用于虚拟语气和试探性语气","desc":"虚拟语气可指现在或将来的情况；I thought... 可作试探性的询问、请求、建议。","good":["If I were you, I would do it in another way.","I thought you wanted to have some cakes."],"bad":[]}],"contrasts":[{"title":"used to vs would","head":["对比项","used to","would"],"rows":[["含义","过去常做而现在已终止的动作，强调与现在的关系","只说明过去的动作习惯，和现在没关系"],["时间状语","不必带时间状语","要带时间状语，如 He would drink a lot when he was young."]]}],"pitfalls":["did / didn't 后面的动词必须用原形：× Did Li Ming studied English this morning?","be 动词的句子改为疑问句时不借助 did：× Was Li Ming studied English this morning?","时态要与原句一致：把 He had lunch at school every day last year. 改为否定句应为 He didn't have lunch...，不能改用 doesn't。","used to 的否定式为 didn't use to（或书面语 used not to），不能说 didn't used to。","一般过去时只说明动作发生过，不强调对现在的影响；与现在完成时的区别在于是否与现在有关。"],"examTips":["看到 yesterday、last…、… ago、just now、the other day 等过去时间状语，直接考虑一般过去时。","题干中已有 was、ran 等过去式时，空格处通常也要求过去式（It was great! I met many old friends at the party.）。","有确定过去时间时不用现在完成时：I ___ you played the piano.（选 didn't know）。"],"memoryCard":["be 动词过去式：I/he/she/it 用 was，you/we/they 用 were。","did / didn't 后面跟动词原形。","used to do = 过去常做，现在不做了。"]},"notes":["微信图片_20260927143541_450_66.jpg、微信图片_20260927143554_451_66.jpg 右侧的竖排“注意！失分陷阱！”装饰栏与部分题号被裁切，正文题干可读，已按可识别内容转写。","微信图片_20260927143601_452_66.jpg 至 微信图片_20260927143616_454_66.jpg 为练习页，答案栏为空白（部分选项栏边角被裁切），未编造答案。"],"sectionCount":7},{"topicId":"g-present-perfect","newTopic":false,"title":"动词的完成时","sourceDirs":["yufan/动词/动词时态/完成时"],"imagesRead":17,"summary":"完成时包括现在完成时和过去完成时：现在完成时 have / has + 过去分词，强调过去与现在的联系；过去完成时 had + 过去分词，表示「过去的过去」，常用于宾语从句和间接引语。","intro":"本章（教材第 15 章，P269—P285）在现有「现在完成时」专题之外，补充了现在完成时的完整句型（含特殊疑问句）、过去分词的三种用法、影响/结束/继续/经历四种用法、与一般过去时的辨析、终止性动词、have got、have been to 与 have gone to，以及整个「过去完成时」体系。","extras":{"forms":[{"name":"现在完成时·特殊疑问句","pattern":"疑问词 + have / has + 主语 + 过去分词 + ……?","note":"How long have you been here? / How many times have you been to the Great Wall?"},{"name":"过去完成时","pattern":"had + 过去分词","note":"表示「过去的过去」，否定句在 had 后加 not，疑问句把 had 提到主语之前。"},{"name":"have / has got","pattern":"have / has got + 名词；have / has got + 不定式","note":"形式上是现在完成时，实际与一般现在时的 have / has 意思相同；接不定式表示「必须」。"}],"points":[{"title":"现在完成时与过去完成时的基点不同","desc":"现在完成时以现在的时间为基点；过去完成时以过去的时间为基点，与现在无关，即「过去的过去」。","good":["I have known Neil for three years.","I had known Neil when I was a student.","By six o'clock, I had finished my experiment."],"bad":[]},{"title":"终止性动词要与延续性表达互换","desc":"终止性动词（点动词）不能与表示延续的时间状语连用，要换成延续性表达或改用 ago / since 句型。","good":["(○) I've been away from Shanghai for 3 days.","(○) I left Shanghai 3 days ago.","(○) It is / has been 3 days since I left Shanghai."],"bad":["(×) I've left Shanghai for 3 days.","(×) So you have borrowed it for three days.（应为 have kept）"]},{"title":"have / has been to 与 have / has gone to","desc":"have / has been to 表示去过某地（人已回来，现在不在那里）；have / has gone to 表示去了某地（人已在途中或在那里），不能与表示次数的词连用。","good":["(○) Ronald has been to Hong Kong Disney theme park twice.","(○) Ronald has gone to Hong Kong Disney theme park."],"bad":["(×) Ronald has gone to Hong Kong Disney theme park twice."]},{"title":"过去完成时表示未能实现的愿望","desc":"hope、wish、expect、think、intend、mean、suppose 等表示意向的动词用过去完成时，表示想做而未做的事，意为「原本……，而未能……」。","good":["We had hoped that you would come, but you didn't.","They had been supposed to be able to arrive by ten."],"bad":[]}],"contrasts":[{"title":"现在完成时 vs 过去完成时","head":["项目","现在完成时","过去完成时"],"rows":[["构成","have / has + 过去分词","had + 过去分词"],["时间基点","以现在为基点","以过去某一时间为基点"],["含义","过去发生，与现在有联系","过去的过去"],["例子","I have finished my experiment.","By six o'clock, I had finished my experiment."]]},{"title":"have / has been to vs have / has gone to","head":["结构","含义","例子"],"rows":[["have / has been to","去过（人已回来，现在不在此地）","Ronald has been to Hong Kong Disney theme park twice."],["have / has gone to","去了（人不在此地）","Ronald has gone to Hong Kong Disney theme park."]]}],"pitfalls":["终止性动词（arrive、begin、borrow、buy、come、die、go、join、leave、lose、finish、stop 等）不能与表示延续的时间状语连用；但其否定式构成的是一种可以持续的状态，可以与一段时间连用。","have / has gone to 不能与表示次数的词（twice、three times 等）连用。","have / has got 形式上是现在完成时，意思却等于一般现在时的 have / has，不要按「完成」去理解。"],"examTips":["句中出现 ever、already、for three days、just、never、yet 等词时要用完成时；出现 ago、last 或由 when 引导的问句时不能与完成时连用。","语境判断题先看「现在是否仍有影响」：答语提示现在仍住在英国、现在还在等她时选现在完成时，只叙述过去事实时选一般过去时。","见到 since 引导的时间状语从句，主句用现在完成时；见到 by then、by the end of、by the time 等，考虑过去完成时。"],"memoryCard":["现在完成 = have / has + 过去分词；过去完成 = had + 过去分词。","确定的过去时间（ago、last week、when...）只配一般过去时；不确定的过去时间（ever、already、yet、just、never）才配现在完成时。","过去的过去用过去完成时；终止性动词要变延续性表达。"]},"sectionCount":7},{"topicId":"g-prepositions","newTopic":false,"title":"介词（讲义精讲）","sourceDirs":["yufan/介词"],"imagesRead":23,"summary":"介词是虚词，必须与名词、代词等构成介词短语才能担任句子成分。本章按「介词种类 → 时间介词 → 场所/方向介词 → 其他介词 → 介词固定搭配」系统梳理，并补充 by/until、for/during、in/within、from/since 等易混对比。","intro":"介词数量不多，但每个介词常具有多种意思，使用频率很高。学习时先抓「介词短语的四种句法功能」，再按时间、场所、方向三条线索分类记忆，最后集中突破动词、形容词与介词的固定搭配。","notes":["yufan/介词 目录共 23 张图，已逐张查看：p.124—145（含章节扉页 p.123 的名人名言页）。","p.144—p.145 的「实力测验（Final Check）」为填空练习，仅作说明、未逐题转录；讲解性内容已全部提取。","p.126 左页「注释」小框与 p.132—134 的示意图（on/above/over/under/below、between/among/around、in/into/out of）已转为表格/文字说明，图内箭头示意文字按原图表述。"],"extras":{"forms":[{"name":"期限（截止）","pattern":"by + 时间点","note":"表示「截止到……」，一般和完成时连用：by the end of last year, by next Friday。"},{"name":"直到……为止","pattern":"until / till + 时间点/从句","note":"延续性动词用肯定式（I'll wait for him until he comes here.）；终止性动词要用否定式（They won't come back until the end of the year.）。"},{"name":"一段时间","pattern":"for + 时间段 / during + 期间名词 / through + 时间段","note":"for 后跟表示时间、具体天数等的数字名词；during 后不接数字名词；through 表示从开始到结束。"},{"name":"起点","pattern":"from + 时间点 / since + 时间点或从句","note":"from 可用于各种时态且只能作介词；since 一般只用于完成时的句子，还可作连词。"},{"name":"未来「之后」","pattern":"in + 时间段","note":"以现在为基准，多用于将来时：He will be back in five hours."},{"name":"范围之内","pattern":"within + 时间段","note":"强调「不超过……的范围」，无时态限制：within five minutes."}],"points":[{"title":"否定句中……才（not... until）","desc":"终止性动词与 until / till 连用要用否定式，译成「直到……才……」。","good":["I didn't go to sleep until / till I finished my homework.（直到我做完作业，我才上床睡觉。）","It didn't stop raining till / until midnight.（直到午夜，雨才停。）"],"bad":[]},{"title":"by 与 until / till 的区别","desc":"by 表示截止到某个时间点，until / till 表示动作持续到某个时间点；只有 until / till 能作从属连词引导从句。","good":["Ada had left by the time I arrived.","He stayed there till / until his mother came back."],"bad":[]},{"title":"for 与 during 的区别","desc":"for 之后大多跟表示时间、具体天数等的数字名词；during 后不接表示数字的名词。","good":["He has lived in Los Angeles for 50 years.","Where will you go during the summer?"],"bad":[]},{"title":"in 与 within 的区别","desc":"in 以现在为基准指「从现在起……之后」，多用于将来时；within 强调「在……范围之内」，没有时态限制。","good":["He will be back in five hours.","They finished the work within 2 days at last."],"bad":[]},{"title":"with 与 in 表工具/材料","desc":"用 with 时后面的名词要加冠词或代词；用 in 时后面加物质名词，不能加冠词。","good":["with my ears 用我的耳朵 / with a pencil 用一支铅笔","in ink 用墨水（钢笔）/ in pencil 用铅笔"],"bad":[]},{"title":"in front of 与 in the front of","desc":"in front of 强调外部，in the front of 强调内部。","good":["There is a tree in front of the classroom.（强调外部）","There is a big desk for the teacher in the front of the classroom.（强调内部）"],"bad":[]}],"contrasts":[{"title":"时间介词易混对比","head":["介词","含义","例句"],"rows":[["for","达……之久（+ 数字名词）","He has lived in Los Angeles for 50 years."],["during","在……期间（不接数字名词）","They are going to have a good rest during the winter holidays."],["through","一直……（从开始到结束）","Paul stayed in London through the winter."],["from","从……起（可作介词，不用于完成时限定）","The meeting will be held from eight to ten."],["since","自从……以来（多用于完成时，可作连词）","I have played the piano since 2006."],["in","过……之后（未来时间）","He will be back in five hours."],["within","不超过……的范围","I must finish painting the cat within five minutes."]]},{"title":"方位介词 in / on / to","head":["介词","含义","例句"],"rows":[["in","在某一范围之中（主语被包含在内）","China lies in the east of Asia."],["on","表示两地互相接壤","Canada lies on the north of the USA."],["to","在某一范围之外","China lies to the north of Australia."]]}],"pitfalls":["终止性动词与 until / till 连用要用否定式：They won't come back until the end of the year.（不用 by）","by 与 until / till 不能互换：by seven o'clock 是「截至7点钟」（多与完成时连用），until seven o'clock 是「直到7点（7点以前）」。","英语中有无定冠词 the 意思差别很大：at table 在进餐 / at the table 在桌旁；in prison 在监狱（服刑）/ in the prison 在监狱（工作或探望……）。","in front of 与 before 都可译作「在……之前」，但表示场所时要用 in front of，before 只用于时间、名单或次序等。","表示方位时不能混用 in / on / to：范围内用 in，接壤用 on，范围外用 to。","be famous as（作为……而闻名）与 be famous for（因……而闻名）要区分：He is famous as a scientist. / He is famous for his songs.","hear from 后面跟人，不能跟信：He heard from his mother. = He got a letter from his mother.","listen 强调听的动作（常跟介词 to），hear 强调听的结果：I listened to him, but heard nothing.","在 this、last、next、every 等词前面不能再加介词：this morning / last Friday / next Sunday。"],"examTips":["介词是中考单项填空的高频小词：by / until 的搭配、for / during 与 in / within 的区别、有无 the 的词组辨义（at table / at the table）都常考。","方位介词 in / on / to 是经典易错点：先判断句子的主语在范围内、接壤，还是在范围之外。"],"memoryCard":["by 截止（多完成时），until / till 直到；延续性动词用肯定式，终止性动词用否定式。","for 后接时间段数字，during 后接期间名词，through 表示自始至终。","in 以现在为基准（……之后），within 强调在……范围之内。","有 the 是具体场所，没 the 是本义：at table 吃饭，at the table 在桌旁。","范围内 in，接壤 on，范围外 to。"]},"sectionCount":7},{"topicId":"g-present-continuous","newTopic":false,"title":"现在进行时","sourceDirs":["yufan/动词/动词时态/进行时"],"imagesRead":15,"summary":"第13章把进行时分成现在进行时和过去进行时：构成都是“主语 + be 动词 + 现在分词”，区别只在 be 的形式（am/is/are 或 was/were）；此外还讲了进行时的四种基本用法和“不用于进行时的动词”。","intro":"本章先讲进行时的肯定句、否定句、一般疑问句和特殊疑问句（现在进行时与过去进行时对照），再讲现在进行时、过去进行时的基本用法，并给出常用动词的现在分词表和不用于进行时的动词表。","extras":{"forms":[{"name":"过去进行时","pattern":"was / were + 动词 -ing","note":"I/he/she/it 用 was；you/we/they 用 were。"},{"name":"be going to + 动词原形","pattern":"主语 + be going to + 动词原形","note":"表示即将发生的事或打算（准备）做的事（本章归入将来时）。"}],"points":[{"title":"持续性与短暂性动作同时发生时的分工","desc":"用过去进行时表示持续性动作，用一般过去时表示突然插入的短暂性动作。","good":["We were walking along the river when it rained.","They were watching TV when the lights went out.","When you called, I was having my lunch."],"bad":["We walked along the river when it rained."]},{"title":"过去进行时可表示过去将来","desc":"从过去某一时间看来将要发生的动作，常用在间接引语中。","good":["She went to see David. He was leaving early the next morning.","She asked him whether he was coming back for lunch."],"bad":[]},{"title":"现在进行时可代替一般现在时表示感情色彩","desc":"常与 always、forever 连用，表达不满或赞许。","good":["You are always forgetting the important thing.","Mary is doing pretty well at school."],"bad":["You always forget the important thing.（不表达不满的情绪）"]},{"title":"状态动词一般不用进行时","desc":"表示状态、思想、感情和感觉的动词不用进行时；但 have 表“吃饭、开会”等或 hear 表“听”时可用进行时。","good":["I hear the sound.","I was having dinner when you called me up.","They are hearing an English lecture."],"bad":["I am hearing the sound.","I'm having a lot of books.","We are liking music very much."]}],"contrasts":[{"title":"过去进行时 vs 一般过去时","head":["对比项","一般过去时","过去进行时"],"rows":[["含义","表示一个完成的动作，只说明有过这件事","表示过去某时正在进行的动作，强调动作的连续性"],["例句","The children watched TV yesterday evening.（看过电视，不知看了多久）","The children were watching TV yesterday evening.（整晚都在看电视）"],["搭配","when + 短暂性动作（came home, went out）","when / while + 持续性动作（was cleaning, were playing）"]]}],"pitfalls":["be 动词不能丢：× Listen! Li Ming playing the piano there.（应为 is playing）。","状态动词不用进行时：× We are liking music very much.／× I'm having a lot of books.／× He is looking tired.","现在进行时表将来时须有表示将来的时间状语，且仅限 go、come、leave、start、arrive、return、sleep 等少数动词。","现在进行时与一般现在时区别在“暂时”与“经常”：He walks to work.（习惯）／He's walking to work because his bike is being repaired.（暂时）。"],"examTips":["题干出现 at nine last night、at this time yesterday、at that time 等过去时间点时，用过去进行时。","when 从句用一般过去时、主句表示当时正在进行，主句用过去进行时（When I got there, he was teaching them to dance.）。","看到 now、look、listen 提示正在发生，用现在进行时。"],"memoryCard":["进行时 = be + doing；现在时用 am/is/are，过去时用 was/were。","持续用进行，打断用过去：were doing... when did。","状态动词（like/know/have 表占有）不进进行时。"]},"notes":["微信图片_20260927143932_465_66.jpg 右侧“说明/补充”窄栏被部分裁切，正文可读，已按可识别内容转写。","微信图片_20260927143942_466_66.jpg、微信图片_20260927143947_467_66.jpg 为练习与例题页，右侧题号栏边角被裁切，题干可读；练习答案栏为空白，未编造答案。"],"sectionCount":8},{"topicId":"g-present-simple","newTopic":false,"title":"一般现在时","sourceDirs":["yufan/动词/动词时态/一般现在时"],"imagesRead":15,"summary":"第11章把一般现在时拆成 be 动词与行为动词两套句式：be 动词按主语的人称和数选用 am/is/are，行为动词除第三人称单数加 -s/-es 外都用原形；否定与疑问分别由 be 动词或 do/does 承担。","intro":"本章先讲 be 动词的一般现在时（肯定句、否定句、一般疑问句、特殊疑问句、there be 句型），再讲行为动词的一般现在时（三单变化、否定与疑问句式），最后归纳一般现在时的五种基本用法与中考失分陷阱。","extras":{"forms":[{"name":"there be 句型","pattern":"There is + 单数可数名词/不可数名词 + 地点；There are + 复数名词 + 地点","note":"表示某地有/存在某物。"},{"name":"计划安排（点动词）","pattern":"主语 + 点动词的一般现在时 + 表示将来的时间状语","note":"come/go/start/begin/leave/return/stop 等表示按计划将要发生的动作。"},{"name":"be about to do","pattern":"主语 + be about to + 动词原形","note":"表示马上就要发生的事情，不与将来时间状语连用。"}],"points":[{"title":"be 动词按主语的人称和数选用 am/is/are","desc":"I 用 am；he/she/it 及单数名词用 is；you 及复数用 are。","good":["I am thirteen years old.","Mary is a student.","They are from China."],"bad":["I is thirteen years old.","They is from China."]},{"title":"时间、条件状语从句中用一般现在时表示将来","desc":"if/when/as soon as 引导的从句用一般现在时，主句用一般将来时。","good":["All the students in Class 5 will climb the mountain if it doesn't rain tomorrow.","When he gets to Europe, he will email me."],"bad":["All the students in Class 5 will climb the mountain if it won't rain tomorrow."]},{"title":"表示知觉、态度、感情的动词常用一般现在时","desc":"wonder、like、believe、hope、know、prefer 等词常与一般现在时连用。","good":["I believe him to be honest.","I don't think you are wrong."],"bad":["I am believing him to be honest."]},{"title":"表示普遍真理和特征时不用时间状语","desc":"客观事实用一般现在时陈述。","good":["The sun is bigger than the earth.","Birds fly in the sky."],"bad":[]}],"contrasts":[{"title":"be 动词 vs 行为动词的一般现在时","head":["对比项","be 动词","行为动词"],"rows":[["第三人称单数形式","is（He is a student.）","动词加 -s/-es（He plays.）"],["否定句","主语 + be + not（He isn't a student.）","主语 + don't/doesn't + 动词原形（He doesn't play.）"],["一般疑问句","Am/Is/Are + 主语（Is he a student?）","Do/Does + 主语（Does he play?）"]]}],"pitfalls":["do not 和 does not 后面的动词必须是原形：× He doesn't studies hard.","有 be 动词的句子变否定句、疑问句时不再借助 do/does：× Does he is a student?","there be 句型中 be 的单复数由其后名词决定：There is a pineapple there. / There are many eggs in the kitchen.","点动词用一般现在时表将来时，句中要有表示将来的时间状语；be about to 则相反，不能与将来时间状语连用。"],"examTips":["看到 if / when / as soon as 引导的从句，先想“主将从现”：从句用一般现在时、主句用一般将来时。","第三人称单数主语后动词必须加 -s/-es：usually comes / goes / has。"],"memoryCard":["be 动词三兄弟：I 用 am，he/she/it 用 is，you 和复数用 are。","行为动词：除第三人称单数加 -s/-es 外一律用原形，否定和疑问靠 do/does。","if/when 从句现在时，主句将来时。"]},"notes":["微信图片_20260927101828_426_66.jpg 与 微信图片_20260927101847_428_66.jpg 右侧的“说明/补充/注意”窄栏有一部分被裁切，正文可读，已按可识别内容转写。","微信图片_20260927143336_439_66.jpg 的“汉译英”题干完整可读，答案栏为空白（练习页），未编造答案。"],"sectionCount":7},{"topicId":"g-pronouns","newTopic":false,"title":"代词","sourceDirs":["yufan/代词"],"imagesRead":31,"summary":"代词是代替名词的一种词类。本章按「人称代词—物主代词—指示代词—反身代词—相互代词—不定代词—疑问代词和关系代词」建立体系，并重点辨析 it / one / that、some / any / no / none、other / another / others 等高频易混词。","intro":"整理自教材第 2 章《代词》（第 030—059 页）：先建立代词的分类框架，再逐类掌握变化表与句法功能，最后用中考真题陷阱题与自测题检验。","notes":"第 057 页「实力测验」第 25 题括号内的备选词被手指部分遮挡，按可见内容（something, anything, nothing）记录，存在不确定性；第 057 页第 19、20 题跨页续到第 058 页，第 058 页第 8 题选项续到第 059 页，已按续页内容合并。","extras":{"contrasts":[{"title":"it / one / that 的辨析","head":["代词","含义","例句"],"rows":[["it","指代同类同物，复数用 they / them","May I use your basketball? — Sure, you can use it."],["one","泛指同类异物，不特指；特指用 the one / this one","I haven't got one. (= a pen)"],["that","代表一个对等部分，复数用 those","The weather in Beijing is colder than that in Guangzhou."]]},{"title":"形容词性物主代词 vs 名词性物主代词","head":["属性","能否单独使用","例句"],"rows":[["形容词性","不能，后面必须加名词","This is my book."],["名词性","能，后面不可加名词","This book is mine."]]},{"title":"some 与 any 的用法分工","head":["代词","适用句式","特例"],"rows":[["some","肯定句","表示邀请、请求或期待肯定回答的疑问句中也可用 some"],["any","否定句、疑问句和条件句","肯定句中可表示「任何一个」"]]},{"title":"other 家族一览","head":["形式","含义","例句"],"rows":[["other + 名词","别的……（= others）","other boys (= others) are watching TV"],["the other + 名词","其余的……（= the others = the rest）","The other students (= The others) are boys."],["another","许多中的另外一个（= an other）","Show me another."],["the other","两者中的另外一个","one is Nike shoes, and the other is Adidas"]]}],"points":[{"title":"all、both 的位置","desc":"all、both 的位置和频度副词一样，要放在 be 动词、情态动词及助动词之后，行为动词（实义动词）之前。","good":["They all / both went there.","They were both waiting outside the gate."],"bad":[]},{"title":"none 不能直接跟名词","desc":"none 后面不能直接跟名词，可以单独使用或与 of 连用；no one = nobody，只能指人。","good":["None of the students went there.","None of the T-shirts is clean."],"bad":["None students.","No one of the T-shirts is clean."]},{"title":"复合不定代词与形容词的位置","desc":"something、anything、nothing 等有形容词修饰时，形容词要放在它们的后面。","good":["I have something important to tell you.","There is nothing interesting here."],"bad":["Anything isn't serious."]},{"title":"either / neither / both 的谓语一致","desc":"either、neither 作主语时谓语用单数，both 作主语时谓语用复数；作定语时 neither、either 后接单数名词，both 后接复数名词。","good":["Neither of the movies is good.","Both of the movies are good.","Both teachers often answer the questions."],"bad":[]}],"pitfalls":["人称代词作介词宾语要用宾格，且并列时第二人称在前、第一人称在后：between you and me。","双重所有格用「名词 + of + 名词性物主代词」：some friends of ours。","反身代词必须与相应的名词或代词保持人称和数的一致：They can take care of themselves.","冠词 a / an / the 和 this、that、some 等词后不能加所有格：a friend of mine（正确），a my friend（错误）。","everyone / everybody 作主语时谓语动词用单数，且合成词后不能再加名词。","few、little 形式肯定而意义否定，不能再加 not。","I（我）无论在句首、句中还是句尾都要大写。"],"memoryCard":["代词八类：人称、物主、指示、反身、相互、不定、疑问、关系。","主格作主语，宾格作宾语；形容词性物主代词后必有名词，名词性物主代词后必无名词。","some 用于肯定句与表邀请、请求的疑问句；any 用于否定句、疑问句和条件句。","other 泛指复数用 others，特指其余用 the others（= the rest）。","it 指同类同物，one 指同类异物，that 指对等部分。","all / both 放 be 动词、助动词、情态动词之后，实义动词之前。"]},"sectionCount":13},{"topicId":"g-questions","newTopic":false,"title":"疑问句与疑问词","sourceDirs":["yufan/疑问句"],"imagesRead":17,"summary":"疑问句以提出问题为目的，分为一般疑问句、特殊疑问句、选择疑问句和反意疑问句四种；本章补充分类、各句型构成、疑问代词的形容词用法、how 词组表、选择疑问句与反意疑问句全套规则及答语。","intro":"一般疑问句用 yes / no 回答，特殊疑问句用疑问词开头、不能用 yes / no 回答，选择疑问句用 or 连接两种以上情况，反意疑问句则由“陈述句 + 意思相反的简短问句”构成。语调：一般疑问句、选择疑问句句末多用升调（选择疑问句最后一种用降调），特殊疑问句、反意疑问句（强调时）用降调。","extras":{"forms":[{"name":"一般疑问句（be 动词）","pattern":"Be 动词 + 主语 + ……？","note":"Is he your close friend? —— Yes, he is. / No, he isn't."},{"name":"一般疑问句（情态动词）","pattern":"情态动词 + 主语 + 动词原形 + ……？","note":"Can you bring me some lemons?"},{"name":"一般疑问句（行为动词）","pattern":"Do / Does / Did + 主语 + 动词原形 + ……？","note":"Did he do morning exercises yesterday?"},{"name":"一般疑问句（完成时）","pattern":"Have / Has / Had + 主语 + 过去分词 + ……？","note":"Have you known her since your childhood?"},{"name":"选择疑问句","pattern":"一般疑问句 + or + 被选择的情况？／特殊疑问句，A or B？","note":"Are you a teacher or a student? —— I'm a student."},{"name":"反意疑问句（前肯后否）","pattern":"陈述句, isn't / don't / didn't / can't + 人称代词？","note":"It's a nice day, isn't it?"},{"name":"反意疑问句（前否后肯）","pattern":"否定陈述句, is / do / did + 人称代词？","note":"Mr Smith isn't Austrian, is he?"}],"points":[{"title":"特殊疑问词作主语时用陈述句语序","desc":"what、who、which 在疑问句中作主语时，句子语序仍是陈述句语序，不再倒装。","good":["Who broke the window? — Li Ming did.","What is in the room? — There are a lot of chairs in it."],"bad":["Who did break the window?"]},{"title":"what、whose、which 可作形容词，后接名词","desc":"这三个疑问词后跟名词时起形容词作用，可对主语、表语和宾语提问。","good":["Whose pens are these?","What size shoes do you take?","Which book did you read?"],"bad":[]},{"title":"when 不能与完成时连用","desc":"when 询问具体时间，问“多久”要用 how long。","good":["How long have you been here?","When did you come here?"],"bad":["When have you been here?"]},{"title":"反意疑问句的答语与汉语习惯不同","desc":"根据实际情况回答：事实是肯定的用 Yes + 肯定结构，事实是否定的用 No + 否定结构。","good":["A: You're not ready, are you? B: Yes, I am.（不，我准备好了。）","A: Mr Smith isn't Austrian, is he? B: No, he isn't.（是的，他不是。）"],"bad":[]},{"title":"祈使句与 Let's 的反意问句","desc":"肯定祈使句后用 will you? / won't you? 等；Let's… 后用 shall we?，Let us / me / him… 后用 will you?；否定祈使句后只用 will you?。","good":["Speak louder, will you?","Let's go and see a film, shall we?","Don't be late, will you?"],"bad":["Let us wait for you in the reading room, shall we?"]}],"contrasts":[{"title":"how 词组补充（身高、年龄、距离等）","head":["疑问词","提问内容","典型例句"],"rows":[["How old","岁数","How old are you?"],["How tall","人、树等的高度","How tall is that tree?"],["How high","山等的高度","How high is Mt Fuji?"],["How far","距离","How far is it from A to B?"],["How long","长度","How long is the rope?"]]},{"title":"两种特殊疑问句的语序","head":["疑问词在句中的成分","语序","例句"],"rows":[["作主语","疑问词 + 谓语 + ……（陈述句语序）","Who broke the window? / What is in the room?"],["作宾语/状语等","疑问词 + 助动词/be + 主语 + 动词……","What do you want to be? / When were you born?"]]}],"pitfalls":["“Can you…?”与“Can't you…?”口气不同：后者带惊讶、责难、反问意味，不表示委婉请求。","反意疑问句的简短问句必须用缩略形式，主语必须用人称代词（不能用名词）。","陈述部分含 never / seldom / hardly / few / little / nobody / nothing / neither 等否定意义词时，疑问部分用肯定式。","含 I think / believe / suppose / imagine 等宾语从句的复合句，反意疑问部分随从句的谓语动词和主语。","动词 have 表“有”时反意疑问句两种形式均可（hasn't he? / doesn't he?）；表“经历、开会、吃”等时只能用 do 的相应形式。"],"examTips":["看到选项里出现 or 连接两种情况，先想到选择疑问句，答语不能用 yes / no。","反意疑问句先判断前一部分的肯/否，再“前肯后否、前否后肯”，并检查人称代词与缩略形式。","答语类题目按事实回答：事实肯定用 Yes，事实否定用 No，注意与汉语“是的/不”的语序差异。"],"memoryCard":["四类疑问句：一般、特殊、选择、反意。","前肯后否，前否后肯；答语按事实。","Let's 用 shall we，Let us 用 will you。"]},"notes":["图片 微信图片_20260927154058_562_66.jpg 为第 20 章章首页（名人名言页），无语法正文，已记录其名言与译文。","其余 16 张图片（563—578）内容清晰，均可逐字转写；无不可识别图片。","与 topics.js 现有 g-questions 内容（how long / how often / how soon / how much / how many 辨析与答语反推法）不重复，本文件只补充分类、构成、疑问代词/副词用法、选择疑问句、反意疑问句与答语规则。"],"sectionCount":8},{"topicId":"g-reported-speech","newTopic":false,"title":"直接引语与间接引语","sourceDirs":["yufan/直接引语与间接引语"],"imagesRead":15,"summary":"把别人的话转述出来要用间接引语：去掉逗号、冒号、引号，调整人称与时态，变化时间/地点状语和指示代词，并按陈述句、疑问句、祈使句、感叹句四类句型分别改造，转述后大多构成一个宾语从句。","intro":"教材第二十三章·直接引语与间接引语共三大块：1 直接引语与间接引语的构成；2 直接引语与间接引语的转化（人称、时态、时间/地点状语和指示代词、四类句型）；3 直接引语与间接引语需注意的事项（时态不变、人称不变、主句动词、情态动词、请求句）。以下按图片原顺序整理为讲义。","notes":"第 13—15 张（_641_ / _642_ / _643_）为章末「实力测验 Final Check」练习页，原书未附答案，未录入正文；第 1 张（_629_）为章节扉页（仅页眉页脚与章标题），无知识点。其余 11 张均已逐条转写。","extras":{"forms":[{"name":"陈述句转述","pattern":"主句 + (that) + 陈述句","note":"句型、语序不变；that 不作成分，常省略。"},{"name":"特殊疑问句转述","pattern":"主句 + 疑问词 + 陈述语序","note":"语序变陈述语序，句末用句号；不能用 that。"},{"name":"一般疑问句转述","pattern":"主句 + if / whether + 陈述语序","note":"把一般疑问句句型转化为陈述句句型，前置 if 或 whether。"},{"name":"反意疑问句 / 选择疑问句转述","pattern":"主句 + whether + 陈述句 + or not","note":"答语常用 whether...or not；选择疑问句用 whether...or...。"},{"name":"祈使句转述","pattern":"ask / tell / order sb (not) to do sth","note":"改用动词不定式；肯定 sb to do sth，否定 sb not to do sth。"},{"name":"感叹句转述","pattern":"how / what 引导，或 that + 宾语从句","note":"how / what 时语序不变；用 that 时 say 可改为 cry、shout。"}],"points":[{"title":"宾语从句（间接引语）必须用陈述语序","desc":"特殊疑问句转述时，疑问语序要改为陈述语序，句末问号改句号。","good":["Mary asked me what she was doing there.","My teacher asked me how long I had spent in practising those days."],"bad":["Mary asked me what was she doing there.","My teacher asked me how long had I spent in practising those days."]},{"title":"主句是过去时，从句时态要后退","desc":"一般现在时→一般过去时；一般过去时/现在完成时→过去完成时；一般将来时→过去将来时；现在进行时→过去进行时。","good":["She said that she liked maths very much.","He said that he had never seen that man.","Joe said that he was listening to music in his room."],"bad":["She said that she likes maths very much.","He said that he has never seen that man."]},{"title":"人称与时间、地点状语、指示代词同步变化","desc":"人称按汉语习惯调整；today→that day，yesterday→the day before，tomorrow→the next day，here→there，this→that，these→those。","good":["Ben asked me if I wanted to go swimming that day.","Joe said that he was listening to music in his room."],"bad":["Ben asked me if I wanted to go swimming today.","Joe said that he was listening to music in my room."]},{"title":"情态动词必须保留原意","desc":"间接引语中要保留原来直接引语里情态动词的意义，must 常改用 had to。","good":["Tom said that he had to do his homework then."],"bad":["Tom said that he must did his homework then."]}],"contrasts":[{"title":"四类句型转述速查","head":["引用的句子","引导词 / 形式","语序与要点"],"rows":[["陈述句","that（常省略）","句型、语序不变"],["一般疑问句","if / whether","转为陈述句句型，前置 if/whether"],["特殊疑问句","疑问词开头（不用 that）","转为陈述语序，句末用句号"],["反意疑问句","whether ... or not","先看成一般疑问句；选择疑问句用 whether...or..."],["祈使句","ask/tell/order sb (not) to do","改为动词不定式"],["感叹句","how / what，或 that 从句","how/what 时语序不变；say 可改 cry、shout"]]},{"title":"时态变化对照","head":["直接引语","间接引语"],"rows":[["一般现在时","一般过去时"],["一般过去时 / 现在完成时","过去完成时"],["过去完成时","过去完成时（不变）"],["一般将来时","过去将来时"],["现在进行时","过去进行时"],["现在完成进行时","过去完成进行时"],["can / may / shall / will","could / might / should / would"],["could / might / should / would","不变"]]}],"pitfalls":["特殊疑问句转述后仍写成疑问语序（what is she doing→应为 what she was doing），是最常见失分点。","主句是过去时，从句时态忘记后退（he said he is tired 应为 he said he was tired）。","一般疑问句转述忘记加 if / whether；句末问号未改句号。","祈使句转述忘记用不定式，或否定式漏掉 not（应为 tell sb not to do sth）。","时间/地点状语与指示代词忘记同步变化（today→that day，here→there，this→that）。"],"examTips":["【长沙中考】答语“他问我今天早上汤姆什么时候到的学校”→ 特殊疑问句转述：疑问词 + 陈述语序，选 when Tom got to school。","【成都中考】“警察询问这个孩子住在哪里”→ 由题意判断是“住在哪里”，用 where he lived（陈述语序）。","主句 said 是过去时：Tom said he ___ back in a week，直接引语中 will 要变为 would，选 would come。","一般疑问句转述：John asked me ___ to visit his uncle's farm，句型为陈述句且前面加 if/whether，选 whether I would like。"],"memoryCard":["去引号、调人称、退时态、换状语——间接引语四步走。","疑问句转述一律用陈述语序，句末问号变句号。","一般疑问句加 if / whether；祈使句用 ask/tell/order sb (not) to do sth。","主句现在时/将来时、客观真理、动作现在仍存在——这三种情况时态不变。"]},"sectionCount":9},{"topicId":"g-sentence-members","newTopic":true,"title":"句子的成分和基本句型","sourceDirs":["yufan/句子成分和基本句型"],"imagesRead":15,"category":"句法","difficulty":3,"summary":"句子由主语、谓语、表语、宾语、宾语补足语、定语、状语构成；按这些成分的组合方式分为 S+V、S+V+O、S+V+P、S+V+IO+DO、S+V+O+OC 五种基本句型。","intro":"本章先逐个讲清七种句子成分，再把它们组合成五种基本句型。判断宾语后面是“双宾语”还是“复合宾语”，就看宾语与后一个成分能否构成逻辑上的主谓关系。","forms":[{"name":"S + V","pattern":"主语 + 谓语（不及物动词）（+ 状语）","note":"Birds fly. / He runs in the park."},{"name":"S + V + O","pattern":"主语 + 谓语（及物动词）+ 宾语（+ 状语）","note":"She likes English. / I bought a dictionary yesterday."},{"name":"S + V + P","pattern":"主语 + 系动词 + 表语（+ 状语）","note":"They are honest. / It gets dark."},{"name":"S + V + IO + DO","pattern":"主语 + 谓语（及物动词）+ 间接宾语 + 直接宾语（+ 状语）","note":"He gave Tom a present."},{"name":"S + V + O + OC","pattern":"主语 + 谓语（及物动词）+ 宾语 + 宾语补足语（+ 状语）","note":"They made her happy. / I saw her dance."}],"points":[{"title":"不定式作主语，常用 it 作形式主语","desc":"不定式（短语）作主语时，句子常用形式主语 it 句型，真正的主语放到后面。","good":["To teach them English is my job.","It is my job to teach them English."],"bad":["To teach them English is my job. 不能说成 It is my job teach them English.（it 作形式主语时，真正主语的不定式仍要带 to）"]},{"title":"谓语和主语在人称和数上必须一致","desc":"谓语是说明主语“做什么、是什么、怎么样”的成分，位置通常在主语之后；助动词、情态动词要与实义动词一起构成谓语。","good":["David's hobby is writing.","We have finished the work.","He can speak English."],"bad":["We has finished the work.（谓语与主语的人称和数不一致）"]},{"title":"表语位于系动词之后","desc":"名词、代词、形容词、副词、介词短语、不定式等都可以作表语。","good":["We are friends.","You look younger than before.","The two countries are at war now."],"bad":["We are friends. 不能说成 We are friend.（系动词后必须接表语，表语与主语在数上要一致）"]},{"title":"“宾语 + 宾语补足语”是复合宾语","desc":"只有宾语还不能表达完整意思时，要在宾语后加宾语补足语；名词、形容词、副词、介词短语、不定式、现在分词、过去分词都能作宾补。","good":["Leave the door open.","Make yourself at home.","The boss kept him working all day."],"bad":["Leave the door open. 不能说成 Leave the door opens.（宾补用形容词，不随宾语变位）"]},{"title":"用逻辑主谓关系区分双宾语和复合宾语","desc":"宾语与后一成分能构成逻辑上的主谓关系，该成分是宾补（复合宾语）；不能构成，则是双宾语。","good":["He calls me Tom.（me 与 Tom 可理解为“我是汤姆”→ 复合宾语）","She bought me a pen.（me 与 a pen 不构成主谓关系 → 双宾语）"],"bad":["He calls me Tom. 不能当成双宾语来分析（me 与 Tom 是逻辑上的主谓关系）。"]},{"title":"感官、使役动词后作宾补的不定式省 to，变被动要还原","desc":"see / watch / look at / listen to / hear / feel / let / make / have（使得）后的宾补若由不定式担任，则省去 to；变被动语态时 to 要还原。","good":["He saw the pianist play the piano.","The pianist was seen to play the piano."],"bad":["I saw her to enter the shopping mall.（see 后作宾补的不定式要省略 to）"]}],"pitfalls":["双宾语与复合宾语容易混淆：先试加“be”看宾语和后面成分能否构成逻辑主谓关系。","see / watch / hear / make / let 等后的宾补不定式省略 to，但句变为被动语态时 to 必须还原。","形容词作定语修饰由 every-、some-、any-、no- 以及 -thing、-body、-one 构成的合成词时须后置：anyone famous。","不定式修饰名词时一般后置：I have something to do. / She is a nice person to work with.","不及物动词后面不能直接带宾语，但加上介词后可相当于及物动词：You must listen to me."],"examTips":["判断句型先找谓语动词：不及物→S+V；及物后带一个宾语→S+V+O；系动词→S+V+P。","宾语后还有一个名词/形容词/分词时，先判断是双宾语还是复合宾语（逻辑主谓关系）。","非谓语动词作定语、宾补、状语是中考常见考点：注意主动/被动关系，以及不定式是否省 to。"],"memoryCard":["五种句型：S+V、S+V+O、S+V+P、S+V+IO+DO、S+V+O+OC。","双宾语看“给谁/为谁”，复合宾语看“逻辑主谓”。","感官使役省 to，变被动要还原。"],"notes":["图片 微信图片_20260927152929_534_66.jpg 为第 18 章章首页（名人名言页），无语法正文，已按图片内容记录其名言与译文。","其余 14 张图片（535—548）内容清晰，均可逐字转写；无不可识别图片。"],"sectionCount":9},{"topicId":"g-sentence-structure","newTopic":true,"category":"句法","difficulty":5,"title":"句子的结构","sourceDirs":["yufan/句子的结构"],"imagesRead":35,"summary":"按结构英语句子分为简单句、并列句和复合句。简单句有五种基本句型；复合句按从句在句中的功能分为主语从句、宾语从句、表语从句、状语从句和定语从句。","intro":"本讲义整理自教材第二十一章「句子的结构」（共 35 张扫描图）。先整体分清简单句 / 并列句 / 复合句，再逐个吃透五类从句的引导词、语序、时态与易错点。","forms":[{"name":"简单句","pattern":"主语 + 谓语（含五种基本句型）","note":"只包含一个主谓结构，各成分由单词或短语表示。"},{"name":"并列句","pattern":"简单句 + 并列连词 + 简单句","note":"用 and / but / or 等连接，各分句地位平等。"},{"name":"复合句","pattern":"主句 + 连词 + 从句；连词 + 从句 + 主句","note":"含一个主句和一个或一个以上的从句。"},{"name":"主语从句","pattern":"that / whether / 连接代词 / 连接副词 + 陈述语序","note":"在复合句中作主语，不能用 if 引导；常用 it 作形式主语后置。"},{"name":"宾语从句","pattern":"主句 + 连词 + 宾语从句","note":"从句一律用陈述语序；主句过去时，从句用过去的某种时态。"},{"name":"表语从句","pattern":"主语 + be / seem + that / whether / wh- 从句","note":"that 不可省略，表示“是否”只能用 whether。"},{"name":"状语从句","pattern":"从属连词 + 从句","note":"表示时间、原因、条件、目的、结果、让步、比较等。"},{"name":"定语从句","pattern":"先行词 + 关系词 + 从句","note":"关系代词 who / whom / which / whose / that / as；关系副词 when / where / why。"}],"points":[{"title":"宾语从句一律用陈述语序","desc":"把疑问句变为宾语从句时，要把语序改回“主语 + 谓语”，只保留原来的疑问词。","good":["Do you know who he is?","Please let her know when the concert begins.","I asked Tom if he was doing his homework."],"bad":["Do you know who is he?","Please let her know when does the concert begin."]},{"title":"主句是过去时，宾语从句要用过去的某种时态","desc":"主句为一般过去时／过去进行时，从句时态要相应改为过去时、过去进行时、过去将来时或过去完成时。","good":["I knew who lived here.","Our personnel manager asked us if everybody was here."],"bad":["I knew who lives here."]},{"title":"主语从句在句首表示“是否”只能用 whether","desc":"whether 引导主语从句位于句首时不能用 if 或 that 代替。","good":["Whether I will visit Australia this summer has not been decided."],"bad":["If I will visit Australia this summer has not been decided."]},{"title":"表语从句表示“是否”用 whether，且 that 不可省略","desc":"表语从句多在系动词 be、seem 之后；主语是 the reason 时表语从句用 that，不能用 why（否则重复）。","good":["The problem is when we can get our salary.","The reason is that I want to invite you to a party."],"bad":["The reason is why I want to invite you to a party."]},{"title":"非限定性定语从句只能用 which，不能用 that","desc":"非限定性定语从句用逗号分开，关系代词不可省略，也不能用 that。","good":["Beijing, which is the capital of China, is a very beautiful city.","Crusoe's dog, which was very old, became ill and died."],"bad":["Beijing, that is the capital of China, is a very beautiful city."]},{"title":"介词提前时只能用 whom（人）/ which（物）","desc":"介词位于关系代词之前时，指人只能用 whom，指物只能用 which，一律不能省略，也不能用 that / who。","good":["This is the hero of whom we are proud.","Wang Ming wants to find the very pen with which I wrote that letter.","By whom was the novel written?"],"bad":["This is the hero of who we are proud.","By who was the novel written?"]},{"title":"主句是将来时，时间/条件状语从句用一般现在时","desc":"时间状语从句与条件状语从句都遵循“主将从现”。","good":["I'll tell him when he comes back.","We'll make a snowman if it snows heavily this afternoon."],"bad":["I'll tell him when he will come back."]}],"pitfalls":["宾语从句的语序：疑问句变宾语从句后必须用陈述语序，不能保留助动词前置。","whether 与 if：宾语从句中 whether 和 if 一般可互换，但后面跟 or not、或引导介词的宾语从句、或位于句首引导主语从句时，只能用 whether。","because 不能和 so 连用，不能写成“因为……所以……”；though / although 也不能和 but 连用。","定语从句中关系代词已代替先行词作宾语，从句里不能再重复 the record 或用代词 it。","限定性定语从句可用 that；非限定性定语从句不可用 that，也不能省略关系代词。","关系代词 that 不能放在介词后面；介词后面指人只能用 whom。","先行词是 all、much、little、something、everything、anything、nothing、none、the one 等代词，或前面有 only、any、few、little、no、all、one of、the same、the very 以及最高级、序数词时，只宜用 that。","as 代替整个主句时可位于主句前或后，但 which 代表前面整个主句时不能放在主句之前。","“动词 + 介词”构成的短语动词，介词不能前置（take a photo of the girl my mother looks after，不能说 after whom my mother looks）。","定语从句的时态不受主句限制，要根据从句自身的时间状语确定（如 yesterday 就用过去时）。"],"examTips":["北京中考的从句题基本三步走：先看从句缺什么成分（缺主语/宾语用 what、who 等连接代词，不缺成分用 that / whether / if），再看语序是否为陈述语序，最后看时态是否与主句呼应。","看到空格前是介词，直接锁定 which（物）/ whom（人），排除 that 和 who。","看到 the reason 作主语，后面跟表语从句就选 that；the reason 后跟定语从句就选 why / that。","感叹、并列、状语从句的连词题常考 because 与 so、though 与 but 不能连用。"],"memoryCard":["结构三类：简单句、并列句、复合句；从句五类：主、宾、表、状、定。","宾语从句三件事：连词、语序（陈述）、时态（主过从过）。","主语从句句首表“是否”只能用 whether；表语从句 that 不能省。","非限定定语从句：逗号 + which，永不用 that。","介词提前：人用 whom，物用 which。"],"extras":{"forms":[{"name":"复合句三分类","pattern":"简单句 / 并列句 / 复合句","note":"并列句用 and、but、or 等连接；复合句由主句 + 从句构成。"}],"points":[{"title":"so / such 的选择","desc":"名词前用 such；形容词/副词前用 so。不可数名词或复数名词前只能用 such，但被 much、little、many、few 修饰时要用 so。","good":["It's such nice weather that all of us want to go to the park.","He had so much homework to do that he had to decide not to see the film that night.","I have had so many falls that I am black and blue all over."],"bad":["It's so nice weather that all of us want to go to the park."]},{"title":"too...to 与 not...until 的改写","desc":"so...that 结果句可改写为 too...to 简单句；after 从句可改写为 not...until 结构。","good":["She was too exhausted to have dinner.","He won't watch TV until he finishes his work."],"bad":["She was so exhausted that she couldn't have dinner.（原句正确，但改写简单句时不能再保留 so...that）"]}],"contrasts":[{"title":"从句引导词速查","head":["从句","引导词","关键规则"],"rows":[["主语从句","that / whether / 连接代词 / 连接副词","句首表“是否”只能用 whether；常用 it 作形式主语"],["宾语从句","that / whether / if / 连接代词 / 连接副词","陈述语序；主过从过"],["表语从句","that / whether / wh- / because","that 不可省略；the reason 后用 that"],["状语从句","when / while / as / since / if / unless / so that / though / than 等","主将从现；because 不与 so 连用"],["定语从句","关系代词 + 关系副词","限定性可用 that，非限定性不可用 that"]]}]},"sectionCount":8},{"topicId":"g-sentence-types","newTopic":true,"category":"句法","difficulty":3,"title":"句子的种类","sourceDirs":["yufan/句子的种类"],"imagesRead":13,"summary":"按使用目的，英语句子分为陈述句、疑问句、祈使句和感叹句四种。本章重点是陈述句的否定结构（含部分否定、否定前移）、祈使句的肯定与否定形式，以及 what / how 引导的感叹句。","intro":"本讲义整理自教材第十九章「句子的种类」（共 13 张扫描图）。疑问句内容较多，教材安排在下一章（第二十章）详述，本讲义不重复；这里集中整理陈述句（肯定/否定）、祈使句与感叹句。","forms":[{"name":"陈述句","pattern":"主语 + 谓语（肯定）／主语 + be / 情态动词 / 助动词 + not ...（否定）","note":"陈述事实或观点，用降调，句末用句号。"},{"name":"疑问句","pattern":"一般疑问句／特殊疑问句等","note":"本书安排在第 20 章详述；本章只作分类提示。"},{"name":"祈使句","pattern":"动词原形 + ...（省略主语）","note":"表示请求、命令、建议；句末用感叹号或句号，用降调。"},{"name":"否定祈使句","pattern":"Don't + 动词原形 ...；Let's / Let me + not + 动词原形 ...","note":"Don't let + 第三人称代词宾格/名词 + 动词原形。"},{"name":"感叹句（what）","pattern":"What + a/an（+ 形容词）+ 名词 + 陈述句！","note":"what 修饰名词。"},{"name":"感叹句（how）","pattern":"How + 形容词/副词 + 陈述句（主语 + 谓语）！","note":"how 修饰形容词、副词；how 修饰动词时动词不提前。"}],"points":[{"title":"含有 not 的部分否定","desc":"not 与 very、always 以及不定代词 all、both、every 及 every 的复合词连用时，表示部分否定。","good":["I don't play football very well.（我足球踢得不是很好。）","It isn't always hot here in summer.（这里夏天不一定总是很热。）","All of us are not students.（我们并非都是学生。）"],"bad":["All of us are not students.（想表达“我们都不是学生”时应说 None of us are students.）"]},{"title":"宾语从句的否定前移","desc":"主句谓语是 think、believe 等词时，宾语从句谓语的否定习惯上要前移到主句谓语前。","good":["I don't think you are right.","We don't believe he'll win."],"bad":["I think you aren't right.（不符合习惯表达）"]},{"title":"祈使句 + and / or 相当于条件状语从句","desc":"祈使句有时相当于一个由 if 引导的条件状语从句；and 表顺承，or 表否则。","good":["Use your head, and you'll find a way.","Hurry up, or you'll miss the train."],"bad":["Use your head, or you'll find a way.（and / or 关系用错）"]},{"title":"感叹句 what 与 how 的分工","desc":"what 修饰名词（单数可数名词要加 a/an）；how 修饰形容词、副词。","good":["What a clever boy he is!","What nice weather it is!","How clever the boy is!","How fast he runs!"],"bad":["How a clever boy he is!","What clever the boy is!"]},{"title":"Let's 与 Let us 的区别","desc":"Let's 包括对方，Let us 不包括对方，在反意疑问句中差别最明显。","good":["Let's go, shall we?","Let us go, will you?"],"bad":["Let's go, will you?（表示包括对方的建议时应用 shall we）"]},{"title":"用 no / never / few / little 等否定词表示否定","desc":"no + 名词 = not any；never 语气比 not 强烈；few / little 表示“几乎没有”；no one = nobody；nothing = not anything；seldom、hardly 是否定副词。","good":["There is no wind. = There is not any wind.","I'll never forget you.","No one knows the answer. = Nobody knows the answer."],"bad":["There is no any wind.（no 后面不能再加 any）"]}],"pitfalls":["no 和名词之间不能加冠词、指示代词、物主代词以及 much、many、any、some 等限定词。","含 not 的句子中使用 very、always、all、both、every 等时是部分否定，不是全部否定。","few 修饰可数名词复数，little 修饰不可数名词；none 后面常跟 of、可表示人或物，而 nobody 只能表示人。","表示否定的词（never、seldom、hardly、little 等）放在句首时，句子要用倒装结构。","too...to...（太……以至于不……）是不使用否定词的否定句。","祈使句省略主语，谓语动词一律用原形；否定形式是 Don't + 动词原形，不要写成 don't + 其他形式。","please 位于句尾时，前面一定要加逗号；祈使句中的呼语要用逗号隔开。","感叹句中 what 后面要跟名词，how 后面要跟形容词或副词，不能混用。","how 引导的感叹句后面是陈述句语序，而疑问句的语序要颠倒过来（How busy you are! 对 How busy are you?）。","must 作“必须”讲时，mustn't / must not 是“不许（禁止）”，不是“不必要”。","将来时、完成时及情态动词的被动语态，否定词 not 要放在第一个助动词之后（will not be sent，has not been finished），不能放在 be 后面。"],"examTips":["感叹句选择题先看空格后第一个词：是名词短语就用 what（单数可数名词还要看有没有 a/an），是形容词/副词就用 how。","祈使句 + and / or 的题，判断前后是顺承还是相反：顺承用 and，相反（否则）用 or。","含 or not 的空格只能填 whether，不能填 if。","否定转移的标志是主句谓语 think、believe 等，看到 I ______ you are right 这类结构优先考虑否定前移。","陈述句改否定句：有 be 动词、情态动词、完成时助动词就在其后加 not；只有行为动词则借助 do / does / did + not + 动词原形。"],"memoryCard":["句子四类：陈述、疑问、祈使、感叹。","not 遇 very / always / all / both / every = 部分否定。","祈使句：动词原形开头，否定 Don't + 原形。","what 跟名词，how 跟形容词/副词。","祈使句 + and / or = if 条件句。","Let's 包括对方（shall we），Let us 不包括对方（will you）。"],"extras":{"forms":[{"name":"陈述句的否定改写","pattern":"be / 情态动词 / 助动词后加 not；行为动词借助 do / does / did + not","note":"有 be 动词、情态动词、完成时助动词时不再加 do。"}],"points":[{"title":"否定祈使句的两种形式","desc":"直接命令用 Don't + 动词原形；包含说话人自己的建议用 Let's not + 动词原形；涉及第三人称用 Don't let + 宾格/名词 + 动词原形。","good":["Don't be late.","Let's not say anything about it.","Don't let them play with fire."],"bad":["Don't to be late.","Let's don't say anything about it."]}],"contrasts":[{"title":"四种句子速查","head":["类型","形式标志","例句"],"rows":[["陈述句","主语 + 谓语，句末句号","We live in Beijing. / We don't live in Beijing."],["疑问句","助动词/疑问词提前，句末问号","Is this a dog?（详见第二十章）"],["祈使句","动词原形开头，省略主语","Open your eyes! / Don't make such a noise."],["感叹句","what + 名词 / how + 形容词、副词，句末感叹号","What a beautiful building it is! / How hot it is today!"]]}]},"sectionCount":6},{"topicId":"g-verbs-overview","newTopic":true,"title":"动词概说","category":"动词","difficulty":2,"sourceDirs":["yufan/动词/动词概说"],"imagesRead":15,"summary":"动词是句子的重心，说明主语“是什么”或“做什么”，从动词的变化能看出句子是现在、过去还是将来。本章综述动词的种类（行为动词、系动词、助动词、情态动词）、动词的基本形式（原形、第三人称单数、过去式、过去分词、现在分词）、动词的十二种时态形式以及短语动词。","intro":"本章是全书的动词总纲：先讲动词的种类，再讲系动词与行为动词的区分，然后给出动词五种基本形式的构成规则（含不规则动词变化表），最后用 study 为例列出动词十二种时态的形式，为后面各章的具体时态打基础。","forms":[{"name":"行为动词·及物动词(vt.)","pattern":"vt. + 宾语","note":"后面要跟名词或代词作宾语，如 see a film、watch TV。"},{"name":"行为动词·不及物动词(vi.)","pattern":"vi.（+ 介词 + 宾语）","note":"不能直接跟宾语；“不及物动词 + 介词”相当于一个及物动词，如 look at the picture。"},{"name":"系动词(link v.)","pattern":"link v. + 表语","note":"不能单独作谓语，必须和表语一起构成合成谓语，如 I'm a student."},{"name":"助动词(aux.v.)","pattern":"aux.v. + 动词原形/过去分词","note":"本身没有意义，帮助主要动词构成疑问、否定、时态、语态，如 have had、is made。"},{"name":"情态动词(mod.v.)","pattern":"mod.v. + 动词原形","note":"表示说话者的态度，没有人称和数的变化，如 You must study hard."},{"name":"动词的时态","pattern":"动词词形变化 或 加助动词 be/have/has","note":"用动词本身的词形变化或加相关助动词表示动作发生的时间和状态。"}],"points":[{"title":"动词是句子的重心","desc":"每个句子都必须有一个动词来担当谓语，说明主语“是什么”或“做什么”；从动词的变化可以看出该句是现在时、过去时还是将来时。","good":["I am his elder sister.","You study English.","The sun is red."],"bad":[]},{"title":"及物动词后面必须有宾语","desc":"及物动词后跟名词或代词作宾语；及物动词与不及物动词的区分是初中最容易忽略的语法点。","good":["I want to see a film.","Tom is watching TV.","In fact, Scout doesn't like her."],"bad":["We love peace 少了宾语 peace 时不成立。"]},{"title":"同一个动词可以两用（及物/不及物、行为动词/系动词）","desc":"英语中很多动词既是及物又是不及物；look、feel 等既可是行为动词，也可是系动词，要看它后面跟的是宾语还是表语。","good":["Let's begin.（begin 不及物）","We'll begin our class in an hour.（begin 及物）","The girl looks careful.（look 系动词）","The girl looks at the picture carefully.（look 行为动词）"],"bad":["The girl looks carefully.（若想说“看起来细心”应为 The girl looks careful.）"]},{"title":"系动词后面跟表语而不是宾语","desc":"系动词不能单独作谓语，必须和其后的表语（形容词、名词、动名词、不定式、介词短语及副词充当）一起构成合成谓语。","good":["He feels cold.","Steel feels hard.","Silk feels soft and comfortable.","Our dream has come true at last."],"bad":["She is look happy 之类把系动词与行为动词混用。"]},{"title":"助动词与情态动词的判别","desc":"助动词本身没有意义，只帮助主要动词构成谓语；情态动词有词义但不完整，后面一定跟不带 to 的不定式（动词原形，ought to 除外），且没有人称和数的变化。","good":["It is made in China.","I haven't had my breakfast yet.","He can speak English.","He speaks English well."],"bad":["He cans speak English.","You must to study hard."]}],"pitfalls":["汉语中没有及物动词与不及物动词之分，很多同学因此忽略这一点，容易出现“缺宾语/多宾语”的错误。","以 a- 开头的形容词（afraid、asleep、alone、alive、awake）常与系动词连用作表语，不能作前置定语：可以用 The boy asleep is my little brother.，不能用 the asleep boy（应用 the sleeping boy）。","情态动词后要跟动词原形，不能在 can 后加 -s，也不能写成 must to do。","不规则动词要逐组背熟：lie—lay—lain（躺）、lay—laid—laid（放）、lie—lied—lied（说谎）三组最易混。","延续性动词才能和时间段连用（had 可与 for two weeks 搭配，bought 不能）。","词尾 -ed 的读音分三种：清辅音后读[t]，元音和浊辅音后读[d]，辅音 t、d 后读[id]。"],"examTips":["中考常考动词辨义：turn off（关掉）/ turn on（打开）/ turn over（打翻、移交）/ turn down（拒绝、调小）。","spend / pay / take / cost 的辨析：spend...doing sth.、pay sb. for sth.、take 的主语一般是 it 或物。","延续性动词与非延续性动词：How long 提问要用 had 这类延续性动词，不能用 bought。","及物与不及物：arrive / go / get 是不及物动词，要加介词（arrive in/at、go to、get to）；reach 是及物动词，后面直接接地点。"],"memoryCard":["动词是句子的重心，看动词变化定时间。","及物带宾语，不及物加介词。","系动词后跟表语，不单独作谓语。","情态动词后跟原形，没有人称和数的变化。","三单一 -s，过去/过去分词 -ed，现在分词 -ing。"],"notes":["第170—171页、第176—177页为跨页大表（系动词、系动词词组、不规则动词变化表），拍照有轻微倾斜，文字清晰可辨，已按表结构逐格还原。","第180—181页“实力测验”的答案栏在教材原图中为空白，只转写题型与考点，未编造答案。"],"sectionCount":8}];
